import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface SheetData {
  id: string;
  url: string;
  name: string;
  content: string | null;
  status: 'idle' | 'loading' | 'success' | 'error';
  errorMsg?: string;
}

export interface AnalysisResult {
  text: string;
  isStreaming: boolean;
}

/**
 * Converts a Google Sheet 'pubhtml' URL to a CSV export URL.
 * This is the key technical step to make data machine-readable.
 */
export const convertToCsvUrl = (url: string): string => {
  // If it's already a CSV link, return it
  if (url.includes('output=csv')) return url;

  // Replace /pubhtml with /pub?output=csv
  // Pattern: .../d/e/[ID]/pubhtml -> .../d/e/[ID]/pub?output=csv
  return url.replace('/pubhtml', '/pub?output=csv');
};

/**
 * Validates if the URL is a valid published Google Sheet URL.
 */
export const isValidGoogleSheetUrl = (url: string): boolean => {
  return url.includes('docs.google.com/spreadsheets') && url.includes('/pub');
};

import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeSheets = async (
  sheet1Content: string, 
  sheet2Content: string,
  onStream: (text: string) => void
): Promise<void> => {
  const modelId = 'gemini-3-flash-preview'; // Using Flash for speed and large context

  const prompt = `
    你是一位專業的數據分析師。我提供了兩個 Google 試算表的資料 (CSV 格式)。

    請幫我執行以下任務：
    1. **內容識別**：簡要說明這兩份表單各自包含了什麼類型的資料（例如：產品清單、銷售紀錄、庫存等）。
    2. **關聯分析**：分析這兩份表單之間是否有關聯欄位（例如：相同的 ID、名稱）。
    3. **數據洞察**：根據內容提供 3 個有價值的觀察或發現。
    4. **結論**：這兩份資料是否適合整合在一起進行更深入的分析？

    ---
    【表單 1 資料】:
    ${sheet1Content.substring(0, 20000)} ... (截斷以節省長度，若需要更多請告知)

    ---
    【表單 2 資料】:
    ${sheet2Content.substring(0, 20000)} ... (截斷以節省長度)
  `;

  try {
    const response = await ai.models.generateContentStream({
      model: modelId,
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        thinkingConfig: { thinkingBudget: 0 } // Disable thinking for faster feasibility check
      }
    });

    for await (const chunk of response) {
      if (chunk.text) {
        onStream(chunk.text);
      }
    }
  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    throw error;
  }
};

import React, { useState, useEffect } from 'react';
import { SheetData } from './types';
import { convertToCsvUrl } from './utils/sheetHelpers';
import { analyzeSheets } from './services/geminiService';
import FeasibilityCheck from './components/FeasibilityCheck';
import { Loader2, FileSpreadsheet, Play, CheckCircle2, AlertCircle } from 'lucide-react';
import ReactMarkdown from 'react-markdown';

// Pre-defined URLs from the user
const DEFAULT_URL_1 = "https://docs.google.com/spreadsheets/d/e/2PACX-1vT1Vpn2SSkcf7QLqoMoAsdyusxtydfgIQD8pyoV6XojGFnf0zGu_WWuRnI4N3U-Hu0iGRzTrR7N-OD9/pubhtml";
const DEFAULT_URL_2 = "https://docs.google.com/spreadsheets/d/e/2PACX-1vQdHAXZ0A9Uno0bztIwJbuYSmLUAXUR8SDeHn-Z6GWkuwx1PGkUppejuytX2fjB33kRO1hV35Ku31fl/pubhtml";

const App: React.FC = () => {
  const [sheet1, setSheet1] = useState<SheetData>({
    id: '1',
    name: '表單 1',
    url: DEFAULT_URL_1,
    content: null,
    status: 'idle'
