  const [sheet2, setSheet2] = useState<SheetData>({
    id: '2',
    name: '表單 2',
    url: DEFAULT_URL_2,
    content: null,
    status: 'idle'
  });

  const [analysis, setAnalysis] = useState<string>("");
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [useCorsProxy, setUseCorsProxy] = useState(true); // Default to true to increase success rate in pure frontend

  // Function to fetch data
  const fetchData = async (sheet: SheetData, setSheet: React.Dispatch<React.SetStateAction<SheetData>>) => {
    setSheet(prev => ({ ...prev, status: 'loading', errorMsg: undefined }));

    try {
      let fetchUrl = convertToCsvUrl(sheet.url);

      // Detailed comment: In a purely client-side environment (like this preview), 
      // Google Sheets often blocks requests due to CORS. 
      // A common workaround for demos is using a CORS proxy.
      if (useCorsProxy) {
        fetchUrl = `https://api.allorigins.win/raw?url=${encodeURIComponent(fetchUrl)}`;
      }

      const response = await fetch(fetchUrl);

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const text = await response.text();
      setSheet(prev => ({ ...prev, content: text, status: 'success' }));
      return text;
    } catch (err: any) {
      console.error(`Error fetching ${sheet.name}:`, err);
      setSheet(prev => ({ 
        ...prev, 
        status: 'error', 
        errorMsg: '無法讀取資料 (CORS 限制)。在正式開發中，這可以通過後端伺服器輕鬆解決。' 
