    // Reset Analysis
    setAnalysis("");
    setIsAnalyzing(true);

    // 1. Fetch Data
    const content1 = await fetchData(sheet1, setSheet1);
    const content2 = await fetchData(sheet2, setSheet2);

    // 2. If both success, send to Gemini
    if (content1 && content2) {
      try {
        await analyzeSheets(content1, content2, (chunk) => {
          setAnalysis(prev => prev + chunk);
        });
      } catch (e) {
        setAnalysis("分析過程中發生錯誤。請確認 API Key 是否正確。");
      }
    } else {
        setAnalysis("無法讀取表單資料，請檢查上方錯誤訊息。這通常是因為瀏覽器安全限制，這正是在「可行性評估」中需要注意的技術點。");
    }

    setIsAnalyzing(false);
  };

  return (
    <div className="min-h-screen p-8 max-w-5xl mx-auto">
