            className="rounded border-slate-300"
          />
          使用 CORS Proxy (建議開啟，解決瀏覽器跨域問題)
        </label>
      </div>

      {/* 4. Results Display */}
      {(analysis || isAnalyzing) && (
        <div className="bg-white rounded-2xl shadow-xl border border-slate-200 overflow-hidden animate-in fade-in slide-in-from-bottom-4 duration-700">
          <div className="bg-slate-900 text-slate-100 px-6 py-4 flex items-center justify-between">
            <h2 className="text-lg font-semibold flex items-center gap-2">
              <span className="w-2 h-2 rounded-full bg-blue-400 animate-pulse"></span>
              Gemini 智能分析報告
            </h2>
          </div>
          <div className="p-8 prose prose-slate max-w-none prose-headings:text-slate-800 prose-p:text-slate-600 prose-li:text-slate-600">
            <ReactMarkdown>
              {analysis || "正在等待 Gemini 思考..."}
            </ReactMarkdown>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

/**
 * Converts a Google Sheet 'pubhtml' URL to a CSV export URL.
 * This is the key technical step to make data machine-readable.
 */
export const convertToCsvUrl = (url: string, gid?: string): string => {
  // If it's already a CSV link, return it
  if (url.includes('output=csv') && !gid) return url;

  let baseUrl = url;
  if (url.includes('/pubhtml')) {
    baseUrl = url.replace('/pubhtml', '/pub');
  }

  const separator = baseUrl.includes('?') ? '&' : '?';
  let csvUrl = `${baseUrl}${separator}output=csv`;

  if (gid) {
    csvUrl += `&gid=${gid}`;
  }

  return csvUrl;
};

/**
 * Validates if the URL is a valid published Google Sheet URL.
 */
export const isValidGoogleSheetUrl = (url: string): boolean => {
  return url.includes('docs.google.com/spreadsheets') && url.includes('/pub');
};

/**
 * Extracts available tabs (Sheet Names and GIDs) from the raw HTML of a published sheet.
 * This allows us to access data beyond the first default page.
 */
export const extractTabsFromHtml = (html: string): { name: string; gid: string }[] => {
  const tabs: { name: string; gid: string }[] = [];

  // Pattern 1: Look for the standard Google Sheets embedded JS object structure
  // often looks like: {name:"Jan",gid:"12345"}
  // We use a global regex to find all matches
  const regex = /name:"([^"]+)",gid:"(\d+)"/g;
  let match;

  while ((match = regex.exec(html)) !== null) {
    // Avoid duplicates
    if (!tabs.find(t => t.gid === match![2])) {
      tabs.push({ name: match![1], gid: match![2] });
    }
  }

  // Pattern 2: Sometimes it's in a different format in the HTML menu
  // <li id="sheet-button-12345">...</li>
  // This is a backup if the JS parsing fails
  if (tabs.length === 0) {
     const idRegex = /id="sheet-button-(\d+)"/g;
     while ((match = idRegex.exec(html)) !== null) {
       // Names are harder to parse in this format without DOM, so we use Generic names
       if (!tabs.find(t => t.gid === match![1])) {
        tabs.push({ name: `Sheet (ID: ${match![1]})`, gid: match![1] });
       }
     }
  }

  return tabs;
};

