import FeasibilityCheck from './components/FeasibilityCheck';
import { Loader2, FileSpreadsheet, Play, CheckCircle2, AlertCircle, Layers, Zap } from 'lucide-react';
import ReactMarkdown from 'react-markdown';

// Pre-defined URLs from the user
const DEFAULT_URL_1 = "https://docs.google.com/spreadsheets/d/e/2PACX-1vT1Vpn2SSkcf7QLqoMoAsdyusxtydfgIQD8pyoV6XojGFnf0zGu_WWuRnI4N3U-Hu0iGRzTrR7N-OD9/pubhtml";
const DEFAULT_URL_2 = "https://docs.google.com/spreadsheets/d/e/2PACX-1vQdHAXZ0A9Uno0bztIwJbuYSmLUAXUR8SDeHn-Z6GWkuwx1PGkUppejuytX2fjB33kRO1hV35Ku31fl/pubhtml";

const App: React.FC = () => {
  const [sheet1, setSheet1] = useState<SheetData>({
    id: '1',
    name: '表單 1 (配息資訊 - 單頁)',
    url: DEFAULT_URL_1,
    content: null,
    status: 'idle'
  });

  const [sheet2, setSheet2] = useState<SheetData>({
    id: '2',
    name: '表單 2 (庫存/股價 - 單頁)',
    url: DEFAULT_URL_2,
    content: null,
    status: 'idle'
  });

  const [analysis, setAnalysis] = useState<string>("");
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [useCorsProxy, setUseCorsProxy] = useState(true);
  const [logs, setLogs] = useState<string[]>([]);

  const addLog = (msg: string) => setLogs(prev => [...prev, msg]);

  // Helper to fetch text via proxy
  const fetchText = async (url: string): Promise<string> => {
    let fetchUrl = url;
    if (useCorsProxy) {
      fetchUrl = `https://api.allorigins.win/raw?url=${encodeURIComponent(url)}`;
    }
    const res = await fetch(fetchUrl);
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    return await res.text();
  };

  // Function to fetch data (Capable of handling single or multi, but optimized for single)
  const fetchData = async (sheet: SheetData, setSheet: React.Dispatch<React.SetStateAction<SheetData>>) => {
    setSheet(prev => ({ ...prev, status: 'loading', errorMsg: undefined }));
    addLog(`正在連線至 ${sheet.name}...`);

    try {
      // 1. Fetch the HTML first to check for tabs, just in case, but expect single page now.
      const htmlContent = await fetchText(sheet.url);
      const tabs = extractTabsFromHtml(htmlContent);

      let finalContent = "";

      if (tabs.length > 1) {
        addLog(`${sheet.name}: 警告 - 仍偵測到 ${tabs.length} 個分頁，將嘗試讀取所有內容...`);
        // Fallback for multi-page
        const tabsToFetch = tabs.slice(0, 5); 
        for (const tab of tabsToFetch) {
          const csvUrl = convertToCsvUrl(sheet.url, tab.gid);
          const csvText = await fetchText(csvUrl);
          finalContent += `\n\n=== 分頁: ${tab.name} ===\n${csvText}`;
        }
      } else {
        // Optimized Single Page Path
        addLog(`${sheet.name}: 確認為單頁式結構 (最佳化)。直接讀取資料...`);
        const csvUrl = convertToCsvUrl(sheet.url);
        finalContent = await fetchText(csvUrl);
      }

      setSheet(prev => ({ ...prev, content: finalContent, status: 'success' }));
      return finalContent;

    } catch (err: any) {
      console.error(`Error fetching ${sheet.name}:`, err);
      addLog(`錯誤: ${sheet.name} 讀取失敗 - ${err.message}`);
      setSheet(prev => ({ 
        ...prev, 
        status: 'error', 
        errorMsg: '讀取失敗。' 
      }));
      return null;
    }
  };

  const handleStartAnalysis = async () => {
    setAnalysis("");
    setLogs([]);
    setIsAnalyzing(true);

    const content1 = await fetchData(sheet1, setSheet1);
    const content2 = await fetchData(sheet2, setSheet2);

    if (content1 && content2) {
      addLog("資料讀取完成，啟動 Gemini (含 Google Search 聯網)...");
      try {
        await analyzeSheets(content1, content2, (chunk) => {
          setAnalysis(prev => prev + chunk);
        });
        addLog("分析完成。");
      } catch (e) {
        setAnalysis("分析過程中發生錯誤。請確認 API Key 是否正確。");
      }
    } else {
        setAnalysis("部分資料讀取失敗，請檢查日誌。");
    }

    setIsAnalyzing(false);
  };

  return (
    <div className="min-h-screen p-8 max-w-5xl mx-auto">
      <header className="mb-10 text-center">
        <h1 className="text-4xl font-extrabold text-slate-800 mb-2 tracking-tight">
          Google 表單智慧分析器
        </h1>
        <p className="text-slate-500 font-medium">
          已連接即時聯網引擎 (Live Grounding)
        </p>
      </header>

      <FeasibilityCheck />

      <div className="grid md:grid-cols-2 gap-6 mb-8">
        {[sheet1, sheet2].map((sheet, idx) => (
          <div key={sheet.id} className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex flex-col">
            <div className="bg-slate-50 px-4 py-3 border-b border-slate-100 flex items-center justify-between">
              <div className="flex items-center gap-2 font-semibold text-slate-700">
                <FileSpreadsheet className="w-5 h-5 text-indigo-600" />
                {sheet.name}
              </div>
              {sheet.status === 'success' && (
                 <div className="flex items-center gap-1 text-[10px] bg-green-100 text-green-700 px-2 py-1 rounded font-bold">
                    <CheckCircle2 className="w-3 h-3" />
                    Ready
                 </div>
              )}
            </div>

            <div className="p-4 flex-grow flex flex-col justify-center items-center min-h-[120px]">
              {sheet.status === 'idle' && (
                <div className="text-slate-400 text-sm text-center">
                  等待執行...
                </div>
              )}

              {sheet.status === 'loading' && (
                <div className="flex flex-col items-center text-blue-600">
                  <Loader2 className="w-8 h-8 animate-spin mb-2" />
                  <span className="text-sm">資料同步中...</span>
                </div>
              )}

              {sheet.status === 'success' && (
                <div className="flex flex-col items-center text-green-600 w-full">
                  <div className="mt-2 w-full bg-slate-50 p-2 rounded text-[10px] font-mono text-slate-500 h-24 overflow-hidden border border-slate-100 whitespace-pre-wrap">
                    {sheet.content?.substring(0, 400)}...
                  </div>
                </div>
              )}

              {sheet.status === 'error' && (
                <div className="flex flex-col items-center text-red-500 text-center">
                  <AlertCircle className="w-8 h-8 mb-2" />
                  <span className="text-sm font-medium">讀取失敗</span>
                </div>
              )}
            </div>
          </div>
        ))}
      </div>

      <div className="flex flex-col items-center justify-center mb-10 space-y-4">
        {logs.length > 0 && (
          <div className="w-full max-w-2xl bg-slate-800 text-green-400 p-3 rounded font-mono text-xs mb-4 h-32 overflow-y-auto">
            {logs.map((log, i) => <div key={i}>&gt; {log}</div>)}
          </div>
        )}

        <button
          onClick={handleStartAnalysis}
          disabled={isAnalyzing}
          className={`
            group relative px-8 py-4 rounded-full font-bold text-lg shadow-lg transition-all transform hover:scale-105 active:scale-95
            flex items-center gap-3
            ${isAnalyzing 
              ? 'bg-slate-200 text-slate-400 cursor-not-allowed' 
              : 'bg-gradient-to-r from-green-600 to-teal-600 text-white hover:shadow-green-500/30'}
          `}
        >
          {isAnalyzing ? (
            <>
              <Loader2 className="w-6 h-6 animate-spin" />
              正在聯網查價中...
            </>
          ) : (
            <>
              <Play className="w-6 h-6 fill-current" />
              開始執行 (已最佳化)
            </>
          )}
        </button>
      </div>

      {(analysis || isAnalyzing) && (
        <div className="bg-white rounded-2xl shadow-xl border border-slate-200 overflow-hidden animate-in fade-in slide-in-from-bottom-4 duration-700">
          <div className="bg-slate-900 text-slate-100 px-6 py-4 flex items-center justify-between">
            <h2 className="text-lg font-semibold flex items-center gap-2">
