export const parseEtfData = (csvContent: string): EtfData[] => {
  const lines = csvContent.split(/\r?\n/).filter(line => line.trim() !== '');
  if (lines.length < 2) return [];

  // Simple parser: assuming first column is Code, second is Name if not found in header
  // In a real scenario, we'd map headers dynamically. 
  // For this prototype, we'll try to find known codes.

  const etfs: EtfData[] = [];

  // Skip header, iterate data
  for (let i = 1; i < lines.length; i++) {
    const row = lines[i].split(',').map(c => c.trim());
    // Heuristic: Find the column that looks like a stock code (e.g., 0056)
    const codeIndex = row.findIndex(c => /^[0-9]{4,6}[A-Z]?$/.test(c));

    if (codeIndex !== -1) {
      const code = row[codeIndex];
      const category = CATEGORY_MAP[code];

      // Only process if it's in our interest list
      if (category) {
        // Mocking price data based on string parsing or random if missing (for demo physics)
        // In real app, we would strictly read "Price" column.
        // Assuming: Code, Name, Price...

        let name = row[codeIndex + 1] || code;
        // Clean up name if it contains numbers
        if (/^\d+$/.test(name)) name = "ETF商品";

        // Attempt to parse prices from subsequent columns if they look like numbers
        // This is a fallback parser because we don't know exact column indices from the prompt
        const numericValues = row.slice(codeIndex + 1).map(v => parseFloat(v)).filter(n => !isNaN(n));

        const priceCurrent = numericValues.length > 0 ? numericValues[0] : 0;
        const priceBase = numericValues.length > 1 ? numericValues[1] : priceCurrent * 0.95; // Fake history if missing

        const dividendYield = (Math.random() * 5 + 3).toFixed(2); // Mock for demo
        const returnRate = ((priceCurrent - priceBase) / priceBase * 100);

        etfs.push({
          code,
          name,
          category,
          priceBase: Number(priceBase.toFixed(2)),
          priceCurrent: Number(priceCurrent.toFixed(2)),
          dividendYield: Number(dividendYield),
          estYield: Number(dividendYield) + 0.5,
          returnRate: Number(returnRate.toFixed(2)),
          totalReturn: Number((returnRate + 4).toFixed(2)), // Assume some dividends
          dividends: []
        });
      }
    }
  }

  // If CSV parsing failed to find known codes (e.g. wrong sheet), 
  // we might want to return empty or try another strategy.
  return etfs;
};

