/**
 * Parses the CSV content strictly.
 * It attempts to identify columns by header names first.
 * If headers are not found, it falls back to a position-based approach (Code -> Name -> Price...).
 * NO RANDOM DATA IS GENERATED.
 */
export const parseEtfData = (csvContent: string): EtfData[] => {
  const lines = csvContent.split(/\r?\n/).filter(line => line.trim() !== '');
  if (lines.length < 2) return [];

  const etfs: EtfData[] = [];

  // 1. Analyze Header Row (Index 0)
  const header = lines[0].split(',').map(c => c.trim().toLowerCase());

  // Helper to find column index by keywords
  const findCol = (keywords: string[]) => header.findIndex(h => keywords.some(k => h.includes(k)));

  const idxCode = findCol(['代碼', '代號', 'code', 'symbol', '股票代號']);
  const idxName = findCol(['名稱', 'name', '股票名稱', '商品']);

  // UPDATED LOGIC:
  // User explicitly mentioned "pushed back 1 day" for recent data to ensure validity.
  // Moved '昨日', 'last', 'prev', 't-1' to Current Price detection.
  // Base Price strictly looks for 1/2 or Cost/Base.
  const idxPriceCurrent = findCol(['收盤', '現價', '成交', 'price', 'current', '最近', 'close', '昨日', '昨天', 'prev', 'last', 't-1']);
  const idxPriceBase = findCol(['成本', '1/2', '01/02', '起始', 'base', 'open', 'start', '2025']); 

  const idxYield = findCol(['殖利率', 'yield', '配息率']);
  const idxReturn = findCol(['報酬', '損益', 'return']);

  // 2. Iterate Data Rows
  for (let i = 1; i < lines.length; i++) {
    const row = lines[i].split(',').map(c => c.trim());

    // Attempt to extract Code
    let code = '';
    let name = '';

    // Strategy A: Use detected columns
    if (idxCode !== -1) code = row[idxCode];
    if (idxName !== -1) name = row[idxName];

    // Strategy B: Fallback (Column 0 is usually Code if it matches pattern)
    if (!code) {
        if (/^[0-9]{4,6}[A-Z]?$/.test(row[0])) code = row[0];
        else if (/^[0-9]{4,6}[A-Z]?$/.test(row[1])) code = row[1];
    }

    // Clean code
    code = code.replace(/['"]/g, '').trim();

    // Check if valid ETF code
    const category = CATEGORY_MAP[code];
    if (category) {
        // Fallback for Name if not found
        if (!name && idxName === -1) {
            // Usually Name is next to Code
            const codeIndex = row.findIndex(c => c === code);
            if (codeIndex !== -1 && row[codeIndex + 1]) name = row[codeIndex + 1];
        }

        // --- Extract Numeric Data STRICTLY ---

        let priceCurrent = 0;
        let priceBase = 0;
        let dividendYield = 0;
        let returnRate = 0;

        // Helper to safely parse float from string like "23.5" or "5.4%"
        const parseNum = (val: string) => {
            if (!val) return 0;
            const clean = val.replace(/[%$,]/g, '');
            const num = parseFloat(clean);
            return isNaN(num) ? 0 : num;
        };

        // 1. Get Price (Current)
        if (idxPriceCurrent !== -1 && row[idxPriceCurrent]) {
            priceCurrent = parseNum(row[idxPriceCurrent]);
        }

        // 2. Get Base Price
        if (idxPriceBase !== -1 && row[idxPriceBase]) {
            priceBase = parseNum(row[idxPriceBase]);
        }

        // 3. Get Yield
        if (idxYield !== -1 && row[idxYield]) {
            dividendYield = parseNum(row[idxYield]);
        }

        // 4. Get Return Rate (or calculate it)
        if (idxReturn !== -1 && row[idxReturn]) {
            returnRate = parseNum(row[idxReturn]);
        } else if (priceBase > 0 && priceCurrent > 0) {
            returnRate = ((priceCurrent - priceBase) / priceBase) * 100;
        }

        // --- Fallback Strategy if Header Detection Failed ---
        if (priceCurrent === 0 && priceBase === 0) {
            // Find all numeric-looking columns after the name
            // excluding the code itself
            const nums = row.map((val, index) => ({ val: parseNum(val), index })).filter(({ val, index }) => {
                const cellContent = row[index];
                const isCode = cellContent.includes(code);
                return !isCode && val > 0;
            });

            // If no headers, we assume the user put the "Latest" price closer to the name or first numeric
            // Adjusting based on user input: likely PriceCurrent first, then Base?

            if (nums.length >= 1) priceCurrent = nums[0].val; // First number found
            if (nums.length >= 2) priceBase = nums[1].val;    // Second number found
            if (nums.length >= 3 && nums[2].val < 20) dividendYield = nums[2].val; 
        }

        // --- Final Object Construction ---
        etfs.push({
            code,
            name: name || code, // fallback name
            category,
            priceBase: Number(priceBase.toFixed(2)),
            priceCurrent: Number(priceCurrent.toFixed(2)),
            dividendYield: Number(dividendYield.toFixed(2)),
            estYield: 0, 
            returnRate: Number(returnRate.toFixed(2)),
            totalReturn: Number(returnRate.toFixed(2)), 
            dividends: []
        });
    }
  }

  return etfs;
};

