/**
 * Parses the CSV content strictly with robust header detection.
 */
export const parseEtfData = (csvContent: string): EtfData[] => {
  const lines = csvContent.split(/\r?\n/).filter(line => line.trim() !== '');
  if (lines.length < 2) return [];

  const etfs: EtfData[] = [];

  // --- 1. Robust Header Row Detection ---
  // Scan first 10 lines to find the true header row.
  // It MUST contain 'code'/'代號' AND 'name'/'名稱'.
  let headerRowIndex = -1;
  let header: string[] = [];

  for (let i = 0; i < Math.min(lines.length, 10); i++) {
     const rowLower = lines[i].toLowerCase();
     if ((rowLower.includes('代碼') || rowLower.includes('代號') || rowLower.includes('code') || rowLower.includes('symbol')) &&
         (rowLower.includes('名稱') || rowLower.includes('name') || rowLower.includes('商品'))) {
         headerRowIndex = i;
         header = lines[i].split(',').map(c => c.trim().toLowerCase());
         console.log("Found Header Row at index:", i, header);
         break;
     }
  }

  // Fallback: If scan fails, assume row 0 is header
  if (headerRowIndex === -1) {
     headerRowIndex = 0;
     header = lines[0].split(',').map(c => c.trim().toLowerCase());
  }

  // Helper to find column index by keywords
  const findCol = (keywords: string[]) => header.findIndex(h => keywords.some(k => h.includes(k)));

  const idxCode = findCol(['代碼', '代號', 'code', 'symbol', '股票代號']);
  const idxName = findCol(['名稱', 'name', '股票名稱', '商品']);

  // --- 2. Price Column Detection (Prioritized) ---
  // Priority 1: Specific dates requested by user
  let idxPriceCurrent = findCol([
      '2025/12/24', '12/24', 
      '2025/12/25', '12/25', 
      '2025/12/23', '12/23',
      '2025/12/26', '12/26'
  ]);

  // Priority 2: Generic "Current Price" keywords
  if (idxPriceCurrent === -1) {
    idxPriceCurrent = findCol(['收盤', '現價', '成交', 'price', 'current', '最近', 'close', 'last', '昨日']);
  }

  // Base Price
  const idxPriceBase = findCol(['成本', '1/2', '01/02', '起始', 'base', 'open', 'start']); 

  const idxYield = findCol(['殖利率', 'yield', '配息率']);
  const idxReturn = findCol(['報酬', '損益', 'return']);

  // --- 3. Parse Data Rows ---
  for (let i = headerRowIndex + 1; i < lines.length; i++) {
    const row = lines[i].split(',').map(c => c.trim());

    // Attempt to extract Code
    let code = '';
    let name = '';

    // Strategy A: Use detected columns
    if (idxCode !== -1 && row[idxCode]) code = row[idxCode];
    if (idxName !== -1 && row[idxName]) name = row[idxName];

    // Strategy B: Fallback (Column 0 is usually Code)
    if (!code) {
        if (/^[0-9]{4,6}[A-Z]?$/.test(row[0])) code = row[0];
        else if (/^[0-9]{4,6}[A-Z]?$/.test(row[1])) code = row[1];
    }

    // Clean code
    code = code.replace(/['"]/g, '').trim();

    // Check if valid ETF code
    const category = CATEGORY_MAP[code];
    if (category) {
        // Fallback for Name if not found
        if (!name && idxName === -1) {
            const codeIndex = row.findIndex(c => c === code);
            if (codeIndex !== -1 && row[codeIndex + 1]) name = row[codeIndex + 1];
        }

        // --- Market Label ---
        let marketLabel = '上市';
        if (category === 'AE' || code.includes('B') || name.includes('債')) {
            marketLabel = '上櫃';
        }

        // --- Extract Numeric Data ---
        let priceCurrent = 0;
        let priceBase = 0;
        let dividendYield = 0;
        let returnRate = 0;

        const parseNum = (val: string) => {
            if (!val) return 0;
            const clean = val.replace(/[%$,]/g, '');
            const num = parseFloat(clean);
            return isNaN(num) ? 0 : num;
        };

        if (idxPriceCurrent !== -1 && row[idxPriceCurrent]) {
            priceCurrent = parseNum(row[idxPriceCurrent]);
        }

        if (idxPriceBase !== -1 && row[idxPriceBase]) {
            priceBase = parseNum(row[idxPriceBase]);
        }

        if (idxYield !== -1 && row[idxYield]) {
            dividendYield = parseNum(row[idxYield]);
        }

        if (idxReturn !== -1 && row[idxReturn]) {
            returnRate = parseNum(row[idxReturn]);
        } else if (priceBase > 0 && priceCurrent > 0) {
            returnRate = ((priceCurrent - priceBase) / priceBase) * 100;
        }

        // --- Ultimate Fallback: Just grab the first few numeric columns ---
        // If we still have 0 for current price, maybe the header match failed slightly but data is there.
        // We assume [Code, Name, Price, ...] or [Code, Price, ...]
        if (priceCurrent === 0) {
             const nums = row.map((val, index) => ({ val: parseNum(val), index }))
                             .filter(({ val, index }) => !isNaN(val) && val > 0 && index !== idxCode);

             // Heuristic: First number is usually Price or Shares. 
             // If it's a "Performance" sheet, usually Price comes early.
             if (nums.length > 0) {
                 // Avoid confusing "Yield" (usually < 20) with Price (usually > 10, but not always)
                 // This is a weak heuristic but better than 0.
                 const possiblePrice = nums.find(n => n.val > 5); 
                 if (possiblePrice) priceCurrent = possiblePrice.val;
             }
        }

        etfs.push({
            code,
            name: name || code, 
            category,
            marketLabel, 
            priceBase: Number(priceBase.toFixed(2)),
            priceCurrent: Number(priceCurrent.toFixed(2)),
            dividendYield: Number(dividendYield.toFixed(2)),
            estYield: 0, 
            returnRate: Number(returnRate.toFixed(2)),
            totalReturn: Number(returnRate.toFixed(2)), 
            dividends: []
        });
    }
  }

  return etfs;
};

