  // Initial Data Fetch
  useEffect(() => {
    const initData = async () => {
      try {
        // Fetch raw CSVs
        const [res1, res2] = await Promise.all([
            fetch(`https://api.allorigins.win/raw?url=${encodeURIComponent(DEFAULT_URL_1)}`),
            fetch(`https://api.allorigins.win/raw?url=${encodeURIComponent(DEFAULT_URL_2)}`)
        ]);

        const txt1 = await res1.text();
        const txt2 = await res2.text();
        setRawData1(txt1);
        setRawData2(txt2);

        // 1. Parse Prices (Sheet 2)
        const parsedEtfs = parseEtfData(txt2);

        // 2. Parse Dividends (Sheet 1)
        const dividendMap = parseDividendData(txt1);

        // 3. Merge Data
        const mergedEtfs = parsedEtfs.map(etf => ({
            ...etf,
            dividends: dividendMap[etf.code] || []
