import React, { useState, useMemo } from 'react';
import { EtfData, CategoryKey, Dividend } from '../types';
import { ArrowUp, ArrowDown, Plus, TrendingUp, CircleAlert, ArrowLeft } from 'lucide-react';

interface Props {
  etfs: EtfData[];
  onAddToPortfolio: (etf: EtfData) => void;
}

// 定義分類配置 (不含 "全部")
const CATEGORY_CONFIG: { key: CategoryKey; label: string }[] = [
  { key: 'AA', label: '季一' },
  { key: 'AB', label: '季二' },
  { key: 'AC', label: '季三' },
  { key: 'AD', label: '月配' },
  { key: 'AE', label: '債券' },
];

const PerformanceView: React.FC<Props> = ({ etfs, onAddToPortfolio }) => {
  const [activeCat, setActiveCat] = useState<CategoryKey>('AA');
  const [selectedEtf, setSelectedEtf] = useState<EtfData | null>(null);

  // 1. 篩選資料
  const filteredEtfs = useMemo(() => {
    return etfs.filter(e => e.category === activeCat);
  }, [etfs, activeCat]);

  // 2. 計算各分類數量 (用於按鈕顯示)
  const categoryCounts = useMemo(() => {
    const counts: Record<string, number> = {};
    etfs.forEach(e => {
        counts[e.category] = (counts[e.category] || 0) + 1;
    });
    return counts;
  }, [etfs]);

  // 顯示用日期
  const displayDate = etfs.length > 0 && etfs[0].dataDate ? etfs[0].dataDate : '最新股價';

  // 輔助函式：判斷是否為未來日期
  const isFutureDate = (dateStr: string) => {
    if (!dateStr) return false;
    // 簡單判斷：假設 dateStr 格式為 YYYY/MM/DD 或 MM/DD (需補年份)
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    let targetDate = new Date(dateStr);
    // 若解析失敗或格式只有 MM/DD，嘗試補上今年或明年
    if (isNaN(targetDate.getTime())) {
        // 簡易處理，實務上需視資料來源格式
        return false; 
    }
    return targetDate > today;
  };

  // --- 詳細資料頁面 ---
  if (selectedEtf) {
      // 根據配息頻率決定顯示筆數 (季配4筆, 月配12筆)
      // AA, AB, AC, AE (債券通常月或季，此處假設債券視同月配或顯示全部，依需求先設 12)
      // AD 為月配
      const isMonthly = selectedEtf.category === 'AD' || selectedEtf.category === 'AE';
      const limit = isMonthly ? 12 : 4;

      // 排序：近 -> 遠 (假設原始資料未排序，先進行排序)
      // 注意：需處理日期格式，這裡假設資料來源格式可比較
      const sortedDividends = [...selectedEtf.dividends].sort((a, b) => {
          return new Date(b.date).getTime() - new Date(a.date).getTime();
      }).slice(0, limit + 1); // 多取一筆備用，或依需求 N+1

      return (
          <div className="bg-white rounded-xl shadow-sm min-h-[400px] flex flex-col">
              <div className="p-4 border-b border-slate-100 flex items-center gap-3 bg-slate-50 rounded-t-xl h-16">
                  <button onClick={() => setSelectedEtf(null)} className="p-2 hover:bg-slate-200 rounded-full">
                      <ArrowLeft className="w-6 h-6 text-slate-700" />
                  </button>
                  <div>
                      <h2 className="text-xl font-bold text-slate-800">{selectedEtf.code} {selectedEtf.name}</h2>
                      <span className="text-sm text-slate-500">配息明細 (近 {limit} 次)</span>
                  </div>
              </div>

              <div className="p-4 overflow-y-auto">
                  <table className="w-full text-left border-collapse">
                      <thead>
                          <tr className="text-slate-500 text-sm border-b border-slate-200">
                              <th className="py-2 font-medium">除息日</th>
                              <th className="py-2 text-right font-medium">金額</th>
                              <th className="py-2 text-right font-medium">狀態</th>
                          </tr>
                      </thead>
                      <tbody>
                          {sortedDividends.length > 0 ? (
                              sortedDividends.slice(0, limit).map((div, idx) => {
                                  const isFuture = isFutureDate(div.date);
                                  return (
                                      <tr key={idx} className={`border-b border-slate-100 ${isFuture ? 'bg-red-50' : ''}`}>
                                          <td className="py-3 text-slate-800 font-medium">{div.date}</td>
                                          <td className="py-3 text-right text-slate-800 font-bold">{div.amount}</td>
                                          <td className="py-3 text-right text-xs">
                                              {isFuture ? <span className="text-red-500 font-bold">預估/未除息</span> : <span className="text-slate-400">已除息</span>}
                                          </td>
                                      </tr>
                                  );
                              })
                          ) : (
                              <tr>
                                  <td colSpan={3} className="py-8 text-center text-slate-400">無配息資料</td>
                              </tr>
                          )}
                      </tbody>
                  </table>

                  <div className="mt-6 p-4 bg-slate-50 rounded-lg text-sm text-slate-500">
                      <p>※ 紅色底色表示為系統判讀之「未來配息資料」或「預估值」。</p>
                  </div>
              </div>
          </div>
      );
  }

  // --- 列表清單頁面 ---
  return (
    <div className="space-y-4 pb-2">
      {/* a. "基準日" 與 "資料日期", 高度為 h20 */}
      <div className="bg-white px-4 rounded-xl shadow-sm border border-slate-200 flex justify-between items-center h-20">
        <div className="flex flex-col justify-center">
          <span className="text-slate-500 text-sm font-medium">基準日 (Base)</span>
          <span className="font-bold text-slate-800 text-xl">2025/1/2</span>
        </div>
        <div className="h-10 w-px bg-slate-200 mx-2"></div>
        <div className="flex flex-col justify-center text-right">
          <span className="text-slate-500 text-sm font-medium">資料日期</span>
          <div className="flex items-center justify-end gap-1">
             <TrendingUp className="w-5 h-5 text-emerald-600" />
             <span className="font-bold text-blue-900 text-xl">{displayDate}</span>
          </div>
        </div>
      </div>

      {/* b. 按鈕功能區 (無 "全部" 按鈕) */}
      <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-hide pt-1">
        {CATEGORY_CONFIG.map((cat) => (
          <button
            key={cat.key}
            onClick={() => setActiveCat(cat.key)}
            className={`
              flex-shrink-0 px-6 py-3 rounded-xl text-lg font-bold transition-all duration-200 whitespace-nowrap shadow-sm border
              ${activeCat === cat.key 
                ? 'bg-blue-900 text-white border-blue-900' 
                : 'bg-white text-slate-500 border-slate-200'}
            `}
          >
            {cat.label} <span className="opacity-70 text-sm font-normal ml-1">({categoryCounts[cat.key] || 0})</span>
          </button>
        ))}
      </div>

      {/* c. 表格內容: 清單方式呈現, 每筆資料有三行 */}
      <div className="space-y-3">
        {filteredEtfs.length > 0 ? (
            filteredEtfs.map((etf) => {
                // 計算預估殖利率邏輯
                // 規則: "這個欄位為 有未來配息之料才計算，否則 輸入 '空值'"
                // 這裡我們檢查 dividends 陣列中是否有未來日期的資料
                const hasFutureData = etf.dividends.some(d => isFutureDate(d.date));
                const estYieldDisplay = hasFutureData && etf.estYield > 0 
                    ? `${etf.estYield}%` 
                    : <span className="text-slate-300">-</span>;

                return (
                    <div key={etf.code} className="bg-white rounded-xl p-4 shadow-sm border border-slate-200 flex flex-col gap-3">
                        {/* 第 1 行: "代碼/名稱", 字體 18px / 16px */}
                        <div className="flex items-baseline gap-2 border-b border-slate-100 pb-2">
                            <span className="text-[18px] font-bold text-slate-900">{etf.code}</span>
                            <span className="text-[16px] text-slate-600 truncate">{etf.name}</span>
                            <span className={`ml-auto text-xs px-1.5 py-0.5 rounded border ${etf.marketLabel === '上櫃' ? 'bg-orange-50 text-orange-700 border-orange-200' : 'bg-slate-50 text-slate-500 border-slate-200'}`}>
                                {etf.marketLabel}
                            </span>
                        </div>

                        {/* 第 2 行: "最近股價", "殖利率", "報酬率", "按鈕" 詳細資料 (+) */}
                        <div className="grid grid-cols-4 items-center gap-2">
                            <div className="flex flex-col">
                                <span className="text-xs text-slate-400">最近股價</span>
                                <span className="text-sm font-bold text-slate-800">{etf.priceCurrent}</span>
                            </div>
                            <div className="flex flex-col text-right">
                                <span className="text-xs text-slate-400">殖利率</span>
                                <span className="text-sm font-bold text-slate-800">{etf.dividendYield}%</span>
                            </div>
                            <div className="flex flex-col text-right">
                                <span className="text-xs text-slate-400">報酬率</span>
                                <span className={`text-sm font-bold ${etf.returnRate >= 0 ? 'text-red-600' : 'text-green-600'}`}>
