                            </div>
                            <div className="text-right">
                                <button 
                                    onClick={() => setSelectedEtf(etf)}
                                    className="w-10 h-10 inline-flex items-center justify-center bg-blue-50 text-blue-700 rounded-lg hover:bg-blue-600 hover:text-white transition-colors"
