import React, { useState, useMemo } from 'react';
import { EtfData, CategoryKey, Dividend } from '../types';
import { ArrowUp, ArrowDown, Plus, TrendingUp, CircleAlert, ArrowLeft } from 'lucide-react';

interface Props {
  etfs: EtfData[];
  onAddToPortfolio: (etf: EtfData) => void;
}

// 定義分類配置 (兩字，無 "全部")
const CATEGORY_CONFIG: { key: CategoryKey; label: string }[] = [
  { key: 'AA', label: '季一' },
  { key: 'AB', label: '季二' },
  { key: 'AC', label: '季三' },
  { key: 'AD', label: '月配' },
  { key: 'AE', label: '債券' },
];

const PerformanceView: React.FC<Props> = ({ etfs, onAddToPortfolio }) => {
  const [activeCat, setActiveCat] = useState<CategoryKey>('AA');
  const [selectedEtf, setSelectedEtf] = useState<EtfData | null>(null);

  // 1. 篩選資料
  const filteredEtfs = useMemo(() => {
    return etfs.filter(e => e.category === activeCat);
  }, [etfs, activeCat]);

  // 顯示用日期
  const displayDate = etfs.length > 0 && etfs[0].dataDate ? etfs[0].dataDate : '最新股價';

  // 輔助函式：判斷是否為未來日期
  const isFutureDate = (dateStr: string) => {
    if (!dateStr) return false;
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    let targetDate = new Date(dateStr);
    if (isNaN(targetDate.getTime())) return false; 
    return targetDate > today;
  };

  // --- 詳細資料頁面 (滿版捲動) ---
  if (selectedEtf) {
      const isMonthly = selectedEtf.category === 'AD' || selectedEtf.category === 'AE';
      const limit = isMonthly ? 12 : 4;

      const sortedDividends = [...selectedEtf.dividends].sort((a, b) => {
          return new Date(b.date).getTime() - new Date(a.date).getTime();
      }).slice(0, limit + 1);

      return (
          <div className="flex flex-col h-full bg-white">
              {/* Header */}
              <div className="h-16 shrink-0 flex items-center px-4 border-b border-slate-100 bg-slate-50 gap-3">
                  <button onClick={() => setSelectedEtf(null)} className="p-2 hover:bg-slate-200 rounded-full">
                      <ArrowLeft className="w-6 h-6 text-slate-700" />
                  </button>
                  <div className="flex-1">
                      <h2 className="text-lg font-bold text-slate-800">{selectedEtf.code} {selectedEtf.name}</h2>
                      <span className="text-xs text-slate-500">配息明細 (近 {limit} 次)</span>
                  </div>
              </div>

              {/* Scrollable Content */}
              <div className="flex-1 overflow-y-auto p-4 scrollbar-hide">
                  <table className="w-full text-left border-collapse">
                      <thead>
                          <tr className="text-slate-500 text-xs border-b border-slate-200">
                              <th className="py-2 font-medium">除息日</th>
                              <th className="py-2 text-right font-medium">金額</th>
                              <th className="py-2 text-right font-medium">狀態</th>
                          </tr>
                      </thead>
                      <tbody>
                          {sortedDividends.length > 0 ? (
                              sortedDividends.slice(0, limit).map((div, idx) => {
                                  const isFuture = isFutureDate(div.date);
                                  return (
                                      <tr key={idx} className={`border-b border-slate-100 ${isFuture ? 'bg-red-50' : ''}`}>
                                          <td className="py-3 text-slate-800 font-medium text-sm">{div.date}</td>
                                          <td className="py-3 text-right text-slate-800 font-bold text-sm">{div.amount}</td>
                                          <td className="py-3 text-right text-xs">
                                              {isFuture ? <span className="text-red-500 font-bold">預估/未除息</span> : <span className="text-slate-400">已除息</span>}
                                          </td>
                                      </tr>
                                  );
                              })
                          ) : (
                              <tr>
                                  <td colSpan={3} className="py-8 text-center text-slate-400 text-sm">無配息資料</td>
                              </tr>
                          )}
                      </tbody>
                  </table>

                  <div className="mt-6 p-4 bg-slate-50 rounded-lg text-xs text-slate-500 leading-relaxed">
                      <p>※ 紅色底色表示為系統判讀之「未來配息資料」或「預估值」。</p>
                  </div>
              </div>
          </div>
      );
  }

  // --- 列表清單頁面 (A1, A2 固定，A3 滑動) ---
  return (
    <div className="flex flex-col h-full bg-slate-50">

      {/* 頂部固定區域 (A1 + A2) */}
      <div className="shrink-0 z-10 bg-slate-50 shadow-sm border-b border-slate-200">

          {/* A1. "基準日" 與 "資料日期", 高度為 h20 */}
          <div className="h-20 bg-white px-4 flex justify-between items-center">
            <div className="flex flex-col justify-center">
              <span className="text-slate-500 text-sm font-light">基準日 (Base)</span>
              <span className="text-slate-800 text-sm font-bold mt-1">2025/1/2</span>
            </div>
            <div className="h-8 w-px bg-slate-100 mx-2"></div>
            <div className="flex flex-col justify-center text-right">
              <span className="text-slate-500 text-sm font-light">資料日期</span>
              <div className="flex items-center justify-end gap-1 mt-1">
                 <TrendingUp className="w-4 h-4 text-emerald-600" />
                 <span className="text-blue-900 text-sm font-bold">{displayDate}</span>
              </div>
            </div>
          </div>

          {/* A2. 按鈕功能區: 季一, 季二... (兩字，無全部，無數量) */}
          <div className="bg-white pb-2 px-2 pt-1 flex gap-2 overflow-x-auto scrollbar-hide">
            {CATEGORY_CONFIG.map((cat) => (
              <button
                key={cat.key}
                onClick={() => setActiveCat(cat.key)}
                className={`
                  flex-shrink-0 px-5 py-2 rounded-lg text-sm font-bold transition-all duration-200 whitespace-nowrap border
                  ${activeCat === cat.key 
                    ? 'bg-blue-900 text-white border-blue-900 shadow-sm' 
                    : 'bg-slate-50 text-slate-500 border-slate-200 hover:bg-slate-100'}
                `}
              >
                {cat.label}
              </button>
            ))}
          </div>
      </div>

      {/* A3. 表格內容: 可滑動區域 (Flex-1) */}
      <div className="flex-1 overflow-y-auto p-3 space-y-3 scrollbar-hide">
        {filteredEtfs.length > 0 ? (
            filteredEtfs.map((etf) => {
                const hasFutureData = etf.dividends.some(d => isFutureDate(d.date));
                const estYieldDisplay = hasFutureData && etf.estYield > 0 
                    ? `${etf.estYield}%` 
                    : <span className="text-slate-300">-</span>;

                return (
                    <div key={etf.code} className="bg-white rounded-xl p-3 shadow-sm border border-slate-200 flex flex-col gap-2">
                        {/* 第 1 行: "代碼/名稱", 字體 18px / 16px */}
                        <div className="flex items-baseline gap-2 border-b border-slate-50 pb-2 mb-1">
                            <span className="text-[18px] font-bold text-slate-900">{etf.code}</span>
                            <span className="text-[16px] text-slate-600 truncate flex-1">{etf.name}</span>
                            <span className={`text-[10px] px-1.5 py-0.5 rounded border ${etf.marketLabel === '上櫃' ? 'bg-orange-50 text-orange-700 border-orange-200' : 'bg-slate-50 text-slate-400 border-slate-200'}`}>
                                {etf.marketLabel}
                            </span>
                        </div>

                        {/* 第 2 行: "最近股價", "殖利率", "報酬率", "按鈕" 詳細資料 (+) */}
                        <div className="grid grid-cols-4 items-center gap-1">
                            <div className="flex flex-col">
                                <span className="text-[10px] text-slate-400">最近股價</span>
                                <span className="text-sm font-bold text-slate-800">{etf.priceCurrent}</span>
                            </div>
                            <div className="flex flex-col text-right">
                                <span className="text-[10px] text-slate-400">殖利率</span>
                                <span className="text-sm font-bold text-slate-800">{etf.dividendYield}%</span>
                            </div>
                            <div className="flex flex-col text-right">
                                <span className="text-[10px] text-slate-400">報酬率</span>
                                <span className={`text-sm font-bold ${etf.returnRate >= 0 ? 'text-red-600' : 'text-green-600'}`}>
                                    {etf.returnRate}%
                                </span>
                            </div>
                            <div className="text-right flex justify-end">
                                <button 
                                    onClick={() => setSelectedEtf(etf)}
                                    className="w-8 h-8 flex items-center justify-center bg-blue-50 text-blue-700 rounded-lg hover:bg-blue-600 hover:text-white transition-colors"
                                >
                                    <Plus className="w-5 h-5" />
                                </button>
                            </div>
                        </div>

                        {/* 第 3 行: "起始股價", "預估殖利率", "含息報酬率", "按鈕" 自組月配 (圈圈+驚嘆號) */}
                        <div className="grid grid-cols-4 items-center gap-1 bg-slate-50/50 -mx-3 px-3 py-1.5 rounded-b-lg">
                            <div className="flex flex-col">
                                <span className="text-[10px] text-slate-400">起始股價</span>
                                <span className="text-sm font-medium text-slate-600">{etf.priceBase}</span>
                            </div>
                            <div className="flex flex-col text-right">
                                <span className="text-[10px] text-slate-400">預估殖利率</span>
                                <span className="text-sm font-medium text-slate-600">{estYieldDisplay}</span>
                            </div>
                            <div className="flex flex-col text-right">
                                <span className="text-[10px] text-slate-400">含息報酬</span>
                                <span className={`text-sm font-medium ${etf.totalReturn >= 0 ? 'text-red-600' : 'text-green-600'}`}>
                                    {etf.totalReturn}%
                                </span>
                            </div>
                            <div className="text-right flex justify-end">
                                <button 
                                    onClick={() => onAddToPortfolio(etf)}
                                    className="w-8 h-8 flex items-center justify-center bg-emerald-50 text-emerald-700 rounded-full hover:bg-emerald-600 hover:text-white transition-colors border border-emerald-100 shadow-sm"
                                >
                                    <CircleAlert className="w-5 h-5" />
                                </button>
                            </div>
                        </div>
                    </div>
                );
            })
        ) : (
            <div className="py-12 text-center text-slate-400 text-sm">
                目前分類無資料
            </div>
        )}
      </div>
    </div>
  );
};

