                        <div className="flex items-baseline gap-2 border-b border-slate-50 pb-1 mb-0.5">
                            <span className="text-[18px] font-bold text-slate-900">{etf.code}</span>
                            {/* 確保是股票名稱 etf.name */}
                            <span className="text-[16px] text-slate-700 font-medium truncate flex-1 leading-tight">{etf.name}</span>

                            <span className={`text-[10px] px-1.5 py-0 rounded border ${etf.marketLabel === '上櫃' ? 'bg-orange-50 text-orange-700 border-orange-200' : 'bg-slate-50 text-slate-400 border-slate-200'}`}>
                                {etf.marketLabel}
