                                    onClick={() => onAddToPortfolio(etf)}
                                    className="w-7 h-7 flex items-center justify-center bg-emerald-100/50 text-emerald-800 rounded-full hover:bg-emerald-200 transition-colors border border-emerald-200/50 shadow-sm"
                                >
                                    <CircleAlert className="w-5 h-5" />
                                </button>
                            </div>
