/**
 * Parses the Dividend CSV content.
 * Returns a map of Code -> Dividend[].
 */
export const parseDividendData = (csvContent: string): Record<string, Dividend[]> => {
  const lines = csvContent.split(/\r?\n/).filter(line => line.trim() !== '');
  if (lines.length < 2) return {};

  const dividendMap: Record<string, Dividend[]> = {};

  // 1. Header Detection
  let headerRowIndex = 0;
  let header = lines[0].split(',').map(c => c.trim().toLowerCase());

  // Simple scan for header if first row isn't it
  if (!header.some(h => h.includes('代號') || h.includes('code'))) {
      for(let i=0; i<Math.min(lines.length, 5); i++) {
          const rowLower = lines[i].toLowerCase();
          if (rowLower.includes('代號') || rowLower.includes('code')) {
              headerRowIndex = i;
              header = lines[i].split(',').map(c => c.trim().toLowerCase());
              break;
          }
      }
  }

  const findCol = (keywords: string[]) => header.findIndex(h => keywords.some(k => h.includes(k)));

  const idxCode = findCol(['代號', 'code', '股票代號']);
  const idxDate = findCol(['除息日', 'date', '配息日', '日期']);
  const idxAmount = findCol(['配息', '金額', 'amount', '現金股利']);

  if (idxCode === -1 || idxAmount === -1) {
      console.warn("Could not find Code or Amount columns in Dividend Sheet");
      return {};
  }

  for (let i = headerRowIndex + 1; i < lines.length; i++) {
      const row = lines[i].split(',').map(c => c.trim());
      // Safety check for row length
      if (row.length <= idxCode) continue;

      const code = row[idxCode]?.replace(/['"]/g, '').trim();

      if (code && CATEGORY_MAP[code]) {
          const amountStr = row[idxAmount]?.replace(/[^0-9.]/g, '') || '0';
          const amount = parseFloat(amountStr);
          const date = idxDate !== -1 ? row[idxDate] : '';

          if (amount > 0) {
              if (!dividendMap[code]) {
                  dividendMap[code] = [];
              }
              dividendMap[code].push({
                  date: date,
                  amount: amount,
                  period: '' 
              });
          }
      }
  }
  return dividendMap;
};

/**
 * Parses the CSV content strictly with robust header detection.
 */
export const parseEtfData = (csvContent: string): EtfData[] => {
  const lines = csvContent.split(/\r?\n/).filter(line => line.trim() !== '');
  if (lines.length < 2) return [];

  const etfs: EtfData[] = [];

  // --- 1. Robust Header Row Detection ---
  let headerRowIndex = -1;
  let header: string[] = [];

  for (let i = 0; i < Math.min(lines.length, 10); i++) {
     const rowLower = lines[i].toLowerCase();
     if ((rowLower.includes('代碼') || rowLower.includes('代號') || rowLower.includes('code') || rowLower.includes('symbol'))) {
         headerRowIndex = i;
         header = lines[i].split(',').map(c => c.trim().toLowerCase());
         break;
     }
  }

  if (headerRowIndex === -1) {
     headerRowIndex = 0;
     header = lines[0].split(',').map(c => c.trim().toLowerCase());
  }

  const findCol = (keywords: string[]) => header.findIndex(h => keywords.some(k => h.includes(k)));

  const idxCode = findCol(['代碼', '代號', 'code', 'symbol', '股票代號']);

  // 修正：嚴格尋找名稱欄位，排除 "商品" (Product) 避免抓到 "季配商品"
  // 優先順序：股票名稱 > ETF名稱 > 名稱 > Name
  const idxName = findCol(['股票名稱', 'etf名稱', '名稱', 'name']);

  const idxMarket = findCol(['市場', 'market', '類別', '上市', '上櫃', 'type', '掛牌']);

  // --- 2. Dynamic Price Column Detection ---
  const dateColIndices = header.map((h, index) => {
      if (/(\d{1,4}[-./]\d{1,2}[-./]\d{1,2})|(\d{1,2}[-./]\d{1,2})/.test(h)) {
          return { index, text: lines[headerRowIndex].split(',')[index].trim() };
      }
      return null;
  }).filter((item): item is { index: number, text: string } => item !== null);

  let idxPriceCurrent = -1;
  let currentPriceDateLabel = '';

  if (dateColIndices.length > 0) {
      const lastDateCol = dateColIndices[dateColIndices.length - 1];
      idxPriceCurrent = lastDateCol.index;
      currentPriceDateLabel = lastDateCol.text;
  } else {
      idxPriceCurrent = findCol(['收盤', '現價', '成交', 'price', 'current', '最近', 'close', 'last']);
      currentPriceDateLabel = '最新股價';
  }

  // Base Price (Cost/Base)
  const idxPriceBase = findCol(['成本', '1/2', '01/02', '起始', 'base', 'open', 'start']); 
  const idxYield = findCol(['殖利率', 'yield', '配息率']);
  const idxReturn = findCol(['報酬', '損益', 'return']);

  // --- 3. Parse Data Rows ---
  for (let i = headerRowIndex + 1; i < lines.length; i++) {
    const row = lines[i].split(',').map(c => c.trim());

    // Safety: ensure row has enough columns for code
    if (idxCode !== -1 && row.length <= idxCode) continue;

    let code = '';
    let name = '';

    if (idxCode !== -1 && row[idxCode]) code = row[idxCode];
    if (idxName !== -1 && row[idxName]) name = row[idxName];

    // Fallback Code detection
    if (!code) {
        if (row[0] && /^[0-9]{4,6}[A-Z]?$/.test(row[0])) code = row[0];
        else if (row[1] && /^[0-9]{4,6}[A-Z]?$/.test(row[1])) code = row[1];
    }

    code = code.replace(/['"]/g, '').trim();
    const category = CATEGORY_MAP[code];

    if (category) {
        // Fallback Name detection: 如果名稱欄位沒抓到，或者抓到的名稱包含 "商品" (表示抓錯欄位)，嘗試代碼右邊那欄
        if ((!name || name.includes('商品')) && idxCode !== -1 && row.length > idxCode + 1) {
            name = row[idxCode + 1];
        }

        // --- Determine Market Label (上市 vs 上櫃) ---
        let marketLabel = '上市';
        if (category === 'AE' || code.includes('B') || (name && name.includes('債'))) {
            marketLabel = '上櫃';
        }

        if (idxMarket !== -1 && row[idxMarket]) {
            const val = row[idxMarket].trim();
            if (val.includes('上櫃') || val.toLowerCase().includes('otc')) {
                marketLabel = '上櫃';
            } else if (val.includes('上市') || val.toLowerCase().includes('listed')) {
                marketLabel = '上市';
            }
        }

        let priceCurrent = 0;
        let priceBase = 0;
        let dividendYield = 0;
        let returnRate = 0;

        const parseNum = (val: string) => {
            if (!val) return 0;
            const clean = val.replace(/[%$,]/g, '');
            const num = parseFloat(clean);
            return isNaN(num) ? 0 : num;
        };

        if (idxPriceCurrent !== -1 && row[idxPriceCurrent]) {
            priceCurrent = parseNum(row[idxPriceCurrent]);
        }

        if (idxPriceBase !== -1 && row[idxPriceBase]) {
            priceBase = parseNum(row[idxPriceBase]);
        }

        if (idxYield !== -1 && row[idxYield]) {
            dividendYield = parseNum(row[idxYield]);
        }

        if (idxReturn !== -1 && row[idxReturn]) {
            returnRate = parseNum(row[idxReturn]);
        } else if (priceBase > 0 && priceCurrent > 0) {
            returnRate = ((priceCurrent - priceBase) / priceBase) * 100;
        }

        // Ultimate Fallback
        if (priceCurrent === 0) {
             const nums = row.map((val, index) => ({ val: parseNum(val), index }))
                             .filter(({ val, index }) => !isNaN(val) && val > 0 && index !== idxCode);
             if (nums.length > 0) {
                 const possiblePrice = nums.find(n => n.val > 5); 
                 if (possiblePrice) priceCurrent = possiblePrice.val;
             }
        }

        etfs.push({
            code,
            name: name || code, 
            category,
            marketLabel, 
            priceBase: Number(priceBase.toFixed(2)),
            priceCurrent: Number(priceCurrent.toFixed(2)),
            dataDate: currentPriceDateLabel,
            dividendYield: Number(dividendYield.toFixed(2)),
            estYield: 0, 
            returnRate: Number(returnRate.toFixed(2)),
            totalReturn: Number(returnRate.toFixed(2)), 
            dividends: [] 
        });
    }
  }

  // 排序：強制依照股票代碼排序
  etfs.sort((a, b) => a.code.localeCompare(b.code));

  return etfs;
};

import React, { useState, useMemo } from 'react';
import { EtfData, CategoryKey, Dividend } from '../types';
import { ArrowUp, ArrowDown, Plus, TrendingUp, CircleAlert, ArrowLeft } from 'lucide-react';

interface Props {
  etfs: EtfData[];
  onAddToPortfolio: (etf: EtfData) => void;
}

// 定義分類配置 (兩字，無 "全部")
const CATEGORY_CONFIG: { key: CategoryKey; label: string }[] = [
  { key: 'AA', label: '季一' },
  { key: 'AB', label: '季二' },
  { key: 'AC', label: '季三' },
  { key: 'AD', label: '月配' },
  { key: 'AE', label: '債券' },
];

// 輔助函式：判斷債券的配息週期類型 (用於顏色與排序)
const getBondType = (code: string): CategoryKey => {
    // 月配債券
    const monthlyBonds = ['00937B', '00933B', '00772B', '00773B', '00942B', '00976B'];
    // 季配債券 (依常見月份分配)
    const groupBlue = ['00720B', '00725B', '00724B']; // 類似季一 (AA)
    const groupGreen = ['00679B', '00795B', '00792B', '00687B']; // 類似季二 (AB)

    if (monthlyBonds.some(b => code.includes(b))) return 'AD';
    if (groupBlue.some(b => code.includes(b))) return 'AA';
    if (groupGreen.some(b => code.includes(b))) return 'AB';
    return 'AC'; // 其餘歸類為季三
};

const PerformanceView: React.FC<Props> = ({ etfs, onAddToPortfolio }) => {
  const activeCatState = useState<CategoryKey>('AA');
  const [activeCat, setActiveCat] = activeCatState;
  const [selectedEtf, setSelectedEtf] = useState<EtfData | null>(null);

  // 1. 篩選與排序資料
  const filteredEtfs = useMemo(() => {
    // 先篩選出當前分類的資料
    let result = etfs.filter(e => e.category === activeCat);

    if (activeCat === 'AE') {
        // 債券特殊排序邏輯：月配(AD) -> 季一(AA) -> 季二(AB) -> 季三(AC)
        // 優先權數值 (越小越前面)
        const priorityMap: Record<string, number> = {
            'AD': 0, // 月配
            'AA': 1, // 季一
            'AB': 2, // 季二
            'AC': 3  // 季三
        };

        result.sort((a, b) => {
            const typeA = getBondType(a.code);
            const typeB = getBondType(b.code);

            // 先比週期
            if (priorityMap[typeA] !== priorityMap[typeB]) {
                return priorityMap[typeA] - priorityMap[typeB];
            }
            // 週期相同比代號
            return a.code.localeCompare(b.code);
        });
    } else {
        // 一般分類：依照股票代號排序
        result.sort((a, b) => a.code.localeCompare(b.code));
    }

    return result;
  }, [etfs, activeCat]);

  // 顯示用日期
  const displayDate = etfs.length > 0 && etfs[0].dataDate ? etfs[0].dataDate : '最新股價';

  // 輔助函式：判斷是否為未來日期
  const isFutureDate = (dateStr: string) => {
    if (!dateStr) return false;
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    let targetDate = new Date(dateStr);
    if (isNaN(targetDate.getTime())) return false; 
    return targetDate > today;
  };

  // --- 顏色樣式邏輯 ---
  const getCardStyle = (etf: EtfData) => {
    let type: CategoryKey = 'AA';

    if (etf.category === 'AE') {
        // 債券使用 helper 判斷
        type = getBondType(etf.code);
    } else {
        // 一般 ETF 直接使用其分類
        type = etf.category;
    }

    switch (type) {
        case 'AA': // 季一：淡藍
            return 'bg-blue-50 border-blue-200';
        case 'AB': // 季二：淡綠
            return 'bg-emerald-50 border-emerald-200';
        case 'AC': // 季三：淡橘
            return 'bg-orange-50 border-orange-200';
        case 'AD': // 月配：淡茶 (Amber)
            return 'bg-amber-50 border-amber-200';
        default:
            return 'bg-white border-slate-200';
    }
  };

  // --- 詳細資料頁面 (滿版捲動) ---
  if (selectedEtf) {
      const isMonthly = selectedEtf.category === 'AD' || selectedEtf.category === 'AE';
      const limit = isMonthly ? 12 : 4;

      const sortedDividends = [...selectedEtf.dividends].sort((a, b) => {
          return new Date(b.date).getTime() - new Date(a.date).getTime();
      }).slice(0, limit + 1);

      return (
          <div className={`flex flex-col h-full ${getCardStyle(selectedEtf).split(' ')[0]}`}>
              {/* Header */}
              <div className="h-16 shrink-0 flex items-center px-4 border-b border-black/5 gap-3 bg-white/60 backdrop-blur-sm">
                  <button onClick={() => setSelectedEtf(null)} className="p-2 hover:bg-black/5 rounded-full">
                      <ArrowLeft className="w-6 h-6 text-slate-700" />
                  </button>
                  <div className="flex-1">
                      <h2 className="text-lg font-bold text-slate-800">{selectedEtf.code} {selectedEtf.name}</h2>
                      <span className="text-xs text-slate-500">配息明細 (近 {limit} 次)</span>
                  </div>
              </div>

              {/* Scrollable Content */}
              <div className="flex-1 overflow-y-auto p-4 scrollbar-hide">
                  <div className="bg-white/80 rounded-xl shadow-sm border border-black/5 overflow-hidden">
                    <table className="w-full text-left border-collapse">
                        <thead>
                            <tr className="text-slate-500 text-xs border-b border-slate-200/50">
                                <th className="py-2 px-4 font-medium">除息日</th>
                                <th className="py-2 px-4 text-right font-medium">金額</th>
                                <th className="py-2 px-4 text-right font-medium">狀態</th>
                            </tr>
                        </thead>
                        <tbody>
                            {sortedDividends.length > 0 ? (
                                sortedDividends.slice(0, limit).map((div, idx) => {
                                    const isFuture = isFutureDate(div.date);
                                    return (
                                        <tr key={idx} className={`border-b border-slate-100/50 ${isFuture ? 'bg-red-50/50' : ''}`}>
                                            <td className="py-3 px-4 text-slate-800 font-medium text-sm">{div.date}</td>
                                            <td className="py-3 px-4 text-right text-slate-800 font-bold text-sm">{div.amount}</td>
                                            <td className="py-3 px-4 text-right text-xs">
                                                {isFuture ? <span className="text-red-500 font-bold">預估/未除息</span> : <span className="text-slate-400">已除息</span>}
                                            </td>
                                        </tr>
                                    );
                                })
                            ) : (
                                <tr>
                                    <td colSpan={3} className="py-8 text-center text-slate-400 text-sm">無配息資料</td>
                                </tr>
                            )}
                        </tbody>
                    </table>
                  </div>

                  <div className="mt-6 p-4 bg-white/60 rounded-lg text-xs text-slate-500 leading-relaxed border border-black/5">
                      <p>※ 紅色底色表示為系統判讀之「未來配息資料」或「預估值」。</p>
                  </div>
              </div>
          </div>
      );
  }

  // --- 列表清單頁面 (A1, A2 固定，A3 滑動) ---
  return (
    <div className="flex flex-col h-full bg-slate-50">

      {/* 頂部固定區域 (A1 + A2) */}
      <div className="shrink-0 z-10 bg-slate-50 shadow-sm border-b border-slate-200">

          {/* A1. "基準日" 與 "資料日期", 高度為 h16, 單行顯示 */}
          <div className="h-16 bg-white px-4 flex justify-between items-center">
            {/* 左側: 基準日 */}
            <div className="flex items-baseline gap-2">
              <span className="text-[12px] text-slate-500 font-light">基準日 (Base)</span>
              <span className="text-[14px] text-slate-900 font-bold">2025/1/2</span>
            </div>

            <div className="h-4 w-px bg-slate-200 mx-1"></div>

            {/* 右側: 資料日期 */}
            <div className="flex items-baseline gap-2">
              <span className="text-[12px] text-slate-500 font-light">資料日期</span>
              <div className="flex items-center gap-1">
                 <span className="text-[14px] text-blue-900 font-bold">{displayDate}</span>
              </div>
            </div>
          </div>

          {/* A2. 按鈕功能區: 季一, 季二... (兩字，無全部，無數量) */}
          <div className="bg-white pb-2 px-2 pt-0 flex gap-2 overflow-x-auto scrollbar-hide">
            {CATEGORY_CONFIG.map((cat) => (
              <button
                key={cat.key}
                onClick={() => setActiveCat(cat.key)}
                className={`
                  flex-shrink-0 px-5 py-2 rounded-lg text-sm font-bold transition-all duration-200 whitespace-nowrap border
                  ${activeCat === cat.key 
                    ? 'bg-blue-900 text-white border-blue-900 shadow-sm' 
                    : 'bg-slate-50 text-slate-500 border-slate-200 hover:bg-slate-100'}
                `}
              >
                {cat.label}
              </button>
            ))}
          </div>
      </div>

      {/* A3. 表格內容: 可滑動區域 (Flex-1) */}
      <div className="flex-1 overflow-y-auto p-2 space-y-2 scrollbar-hide">
        {filteredEtfs.length > 0 ? (
            filteredEtfs.map((etf) => {
                const hasFutureData = etf.dividends.some(d => isFutureDate(d.date));
                const estYieldDisplay = hasFutureData && etf.estYield > 0 
                    ? `${etf.estYield}%` 
                    : <span className="text-slate-300">-</span>;

                // 取得對應顏色樣式
                const cardStyle = getCardStyle(etf);

                return (
                    <div key={etf.code} className={`rounded-lg p-2 shadow-sm border flex flex-col gap-0.5 ${cardStyle}`}>
                        {/* 第 1 行: "股票代碼/股票名稱", 字體 18px / 16px */}
                        <div className="flex items-baseline gap-2 border-b border-black/5 pb-1 mb-0.5">
                            <span className="text-[18px] font-bold text-slate-900">{etf.code}</span>
                            {/* 確保是股票名稱 etf.name */}
                            <span className="text-[16px] text-slate-800 font-medium truncate flex-1 leading-tight">{etf.name}</span>

                            <span className={`text-[10px] px-1.5 py-0 rounded border bg-white/50 border-black/10 text-slate-500`}>
                                {etf.marketLabel}
                            </span>
                        </div>

                        {/* 第 2 行: "最近股價", "殖利率", "報酬率", "按鈕" 詳細資料 (+) */}
                        <div className="grid grid-cols-4 items-center gap-1 leading-tight">
                            <div className="flex flex-col">
                                <span className="text-[12px] font-light text-slate-600 scale-[0.9] origin-left">最近股價</span>
                                <span className="text-[14px] font-bold text-slate-900">{etf.priceCurrent}</span>
                            </div>
                            <div className="flex flex-col text-right">
                                <span className="text-[12px] font-light text-slate-600 scale-[0.9] origin-right">殖利率</span>
                                <span className="text-[14px] font-bold text-slate-900">{etf.dividendYield}%</span>
                            </div>
                            <div className="flex flex-col text-right">
                                <span className="text-[12px] font-light text-slate-600 scale-[0.9] origin-right">報酬率</span>
                                <span className={`text-[14px] font-bold ${etf.returnRate >= 0 ? 'text-red-700' : 'text-green-700'}`}>
                                    {etf.returnRate}%
                                </span>
                            </div>
                            <div className="text-right flex justify-end">
                                <button 
                                    onClick={() => setSelectedEtf(etf)}
                                    className="w-7 h-7 flex items-center justify-center bg-white/60 text-slate-700 rounded-lg hover:bg-white hover:text-black transition-colors border border-black/5"
                                >
                                    <Plus className="w-5 h-5" />
                                </button>
                            </div>
                        </div>

                        {/* 第 3 行: "起始股價", "預估殖利率", "含息報酬率", "按鈕" 自組月配 (圈圈+驚嘆號) */}
                        <div className="grid grid-cols-4 items-center gap-1 bg-white/40 -mx-2 px-2 py-1 rounded-b-lg mt-0.5 leading-tight">
                            <div className="flex flex-col">
                                <span className="text-[12px] font-light text-slate-600 scale-[0.9] origin-left">起始股價</span>
                                <span className="text-[14px] font-bold text-slate-900">{etf.priceBase}</span>
                            </div>
                            <div className="flex flex-col text-right">
                                <span className="text-[12px] font-light text-slate-600 scale-[0.9] origin-right">預估殖利率</span>
                                <span className="text-[14px] font-bold text-slate-900">{estYieldDisplay}</span>
