import React, { useState, useMemo } from 'react';
import { EtfData, CategoryKey, Dividend } from '../types';
import { ArrowUp, ArrowDown, Plus, TrendingUp, CircleAlert, ArrowLeft, RotateCw } from 'lucide-react';

interface Props {
  etfs: EtfData[];
  onAddToPortfolio: (etf: EtfData) => void;
  lastUpdated: Date | null;
  onRefresh: () => void;
  isRefreshing: boolean;
}

// 定義分類配置 (兩字，無 "全部")
const CATEGORY_CONFIG: { key: CategoryKey; label: string }[] = [
  { key: 'AA', label: '季一' },
  { key: 'AB', label: '季二' },
  { key: 'AC', label: '季三' },
  { key: 'AD', label: '月配' },
  { key: 'AE', label: '債券' },
];

// 使用者指定的債券排序列表
const BOND_SPECIFIC_ORDER = [
  '00937B', 
  '00772B', 
  '00933B', 
  '00773B', 
  '00720B', 
  '00725B', 
  '00724B', 
  '00679B', 
  '00761B', 
  '00795B', 
  '00687B', 
  '00751B', 
  '00792B'
];

// 輔助函式：判斷債券的配息週期類型 (用於顏色)
const getBondType = (code: string): CategoryKey => {
    // 月配債券
    const monthlyBonds = ['00937B', '00933B', '00772B', '00773B', '00942B', '00976B'];
    // 季配債券 (依常見月份分配)
    const groupBlue = ['00720B', '00725B', '00724B']; // 類似季一 (AA)
    const groupGreen = ['00679B', '00795B', '00792B', '00687B']; // 類似季二 (AB)

    if (monthlyBonds.some(b => code.includes(b))) return 'AD';
    if (groupBlue.some(b => code.includes(b))) return 'AA';
    if (groupGreen.some(b => code.includes(b))) return 'AB';
    return 'AC'; // 其餘歸類為季三
};

const PerformanceView: React.FC<Props> = ({ etfs, onAddToPortfolio, lastUpdated, onRefresh, isRefreshing }) => {
  const activeCatState = useState<CategoryKey>('AA');
  const [activeCat, setActiveCat] = activeCatState;
  const [selectedEtf, setSelectedEtf] = useState<EtfData | null>(null);

  // 1. 篩選與排序資料
  const filteredEtfs = useMemo(() => {
    // 先篩選出當前分類的資料
    let result = etfs.filter(e => e.category === activeCat);

    if (activeCat === 'AE') {
        // 債券特殊排序邏輯：依照 BOND_SPECIFIC_ORDER 指定順序
        result.sort((a, b) => {
            const indexA = BOND_SPECIFIC_ORDER.indexOf(a.code);
            const indexB = BOND_SPECIFIC_ORDER.indexOf(b.code);

            // 如果兩個都在指定清單中，依清單索引排序
            if (indexA !== -1 && indexB !== -1) {
                return indexA - indexB;
            }

            // 如果 A 在清單中但 B 不在，A 排前面
            if (indexA !== -1) return -1;

            // 如果 B 在清單中但 A 不在，B 排前面
            if (indexB !== -1) return 1;

            // 都不在清單中，依照代碼排序
            return a.code.localeCompare(b.code);
        });
    } else {
        // 一般分類：依照股票代號排序
        result.sort((a, b) => a.code.localeCompare(b.code));
