      <div className="shrink-0 z-10 bg-slate-50 shadow-sm border-b border-slate-200">

          {/* A1. "基準日" 與 "資料日期" (修正：高度 h-16, 單行, 細字12px/粗體14px) */}
          <div className="h-16 bg-white px-4 flex justify-between items-center">
