/**
 * Parses the Dividend CSV content.
 */
export const parseDividendData = (csvContent: string): Record<string, Dividend[]> => {
  const lines = csvContent.split(/\r?\n/).filter(line => line.trim() !== '');
  if (lines.length < 2) return {};

  const dividendMap: Record<string, Dividend[]> = {};

  // 1. Header Detection
  let headerRowIndex = 0;
  // Use parseCSVRow for header as well
  let header = parseCSVRow(lines[0]).map(c => c.trim().toLowerCase());

  // Scan for header if first row isn't it
  if (!header.some(h => h.includes('代號') || h.includes('code') || h.includes('股票代號') || h.includes('symbol'))) {
      for(let i=0; i<Math.min(lines.length, 5); i++) {
          const rowValues = parseCSVRow(lines[i]);
          const rowLower = rowValues.map(c => c.toLowerCase());

          if (rowLower.some(c => c.includes('代號') || c.includes('code') || c.includes('股票代號') || c.includes('symbol'))) {
              headerRowIndex = i;
              header = rowLower;
              break;
          }
      }
  }

  const findCol = (keywords: string[]) => header.findIndex(h => keywords.some(k => h.includes(k)));

  // Enhanced keywords for detection
  const idxCode = findCol(['代號', 'code', '股票代號', 'symbol', '代碼']);
  const idxDate = findCol(['除息日', 'date', '配息日', '日期', '除息交易日', '發放日', '除息']);
  // Broadened amount keywords
  const idxAmount = findCol(['配息', '金額', 'amount', '現金股利', '分配金額', '現金', '股利', 'distribution']);

  if (idxCode === -1 || idxAmount === -1) {
      console.warn("Parse Dividend Failed: Missing required columns (Code or Amount). Header:", header);
      return {};
  }

  for (let i = headerRowIndex + 1; i < lines.length; i++) {
      const row = parseCSVRow(lines[i]);
      if (row.length <= idxCode) continue;

      const rawCode = row[idxCode];
      const code = rawCode ? rawCode.replace(/['"]/g, '').trim() : '';

      // Removed CATEGORY_MAP check here to ensure we capture all data available in the sheet.
      // Filtering will happen when merging with ETF list.
      if (code) {
          const amountStr = row[idxAmount]?.replace(/[^0-9.]/g, '') || '0';
          const amount = parseFloat(amountStr);
          let date = idxDate !== -1 ? row[idxDate] : '';

          if (date) date = date.replace(/['"]/g, '').trim();

          if (amount > 0) {
              if (!dividendMap[code]) {
                  dividendMap[code] = [];
              }
              dividendMap[code].push({
                  date: date,
                  amount: amount,
                  period: '' 
              });
          }
      }
  }
  return dividendMap;
};

/**
 * Parses the CSV content strictly with robust header detection.
 */
export const parseEtfData = (csvContent: string): EtfData[] => {
  const lines = csvContent.split(/\r?\n/).filter(line => line.trim() !== '');
  if (lines.length < 2) return [];

  const etfs: EtfData[] = [];

  // --- 1. Robust Header Row Detection ---
  let headerRowIndex = -1;
  let header: string[] = [];

  for (let i = 0; i < Math.min(lines.length, 10); i++) {
     const rowValues = parseCSVRow(lines[i]);
     const rowLower = rowValues.map(c => c.toLowerCase());

     if (rowLower.some(c => c.includes('代碼') || c.includes('代號') || c.includes('code') || c.includes('symbol'))) {
         headerRowIndex = i;
         header = rowLower;
         break;
     }
  }

  if (headerRowIndex === -1) {
     headerRowIndex = 0;
     header = parseCSVRow(lines[0]).map(c => c.toLowerCase());
  }

  const findCol = (keywords: string[]) => header.findIndex(h => keywords.some(k => h.includes(k)));

  const idxCode = findCol(['代碼', '代號', 'code', 'symbol', '股票代號']);
  const idxName = findCol(['股票名稱', 'etf名稱', '名稱', 'name']);
  const idxMarket = findCol(['市場', 'market', '類別', '上市', '上櫃', 'type', '掛牌']);

  // --- 2. Dynamic Price Column Detection ---
  const dateColIndices = header.map((h, index) => {
      // Matches YYYY/MM/DD, YYYY-MM-DD, MM/DD
      if (/(\d{1,4}[-./]\d{1,2}[-./]\d{1,2})|(\d{1,2}[-./]\d{1,2})/.test(h)) {
          // Re-fetch original casing for display
          const originalHeader = parseCSVRow(lines[headerRowIndex])[index];
          return { index, text: originalHeader.trim() };
      }
      return null;
  }).filter((item): item is { index: number, text: string } => item !== null);

  let idxPriceCurrent = -1;
  let currentPriceDateLabel = '';

  if (dateColIndices.length > 0) {
      const lastDateCol = dateColIndices[dateColIndices.length - 1];
      idxPriceCurrent = lastDateCol.index;
      currentPriceDateLabel = lastDateCol.text;
  } else {
      idxPriceCurrent = findCol(['收盤', '現價', '成交', 'price', 'current', '最近', 'close', 'last']);
      currentPriceDateLabel = '最新股價';
  }

  const idxPriceBase = findCol(['成本', '1/2', '01/02', '起始', 'base', 'open', 'start']); 
  const idxYield = findCol(['殖利率', 'yield', '配息率']);
  const idxReturn = findCol(['報酬', '損益', 'return']);

  // --- 3. Parse Data Rows ---
  for (let i = headerRowIndex + 1; i < lines.length; i++) {
    const row = parseCSVRow(lines[i]);

    if (idxCode !== -1 && row.length <= idxCode) continue;

    let code = '';
    let name = '';

    if (idxCode !== -1 && row[idxCode]) code = row[idxCode];
    if (idxName !== -1 && row[idxName]) name = row[idxName];

    if (!code) {
        if (row[0] && /^[0-9]{4,6}[A-Z]?$/.test(row[0])) code = row[0];
        else if (row[1] && /^[0-9]{4,6}[A-Z]?$/.test(row[1])) code = row[1];
    }

    code = code ? code.replace(/['"]/g, '').trim() : '';

    if (!code) continue;

    const category = CATEGORY_MAP[code];

    if (category) {
        if ((!name || name.includes('商品')) && idxCode !== -1 && row.length > idxCode + 1) {
            name = row[idxCode + 1];
        }

        let marketLabel = '上市';
        if (category === 'AE' || code.includes('B') || (name && name.includes('債'))) {
            marketLabel = '上櫃';
        }

        if (idxMarket !== -1 && row[idxMarket]) {
            const val = row[idxMarket].trim();
            if (val.includes('上櫃') || val.toLowerCase().includes('otc')) {
                marketLabel = '上櫃';
            } else if (val.includes('上市') || val.toLowerCase().includes('listed')) {
                marketLabel = '上市';
            }
        }

        let priceCurrent = 0;
        let priceBase = 0;
        let dividendYield = 0;
        let returnRate = 0;

        const parseNum = (val: string) => {
            if (!val) return 0;
            const clean = val.replace(/[%$,]/g, '');
            const num = parseFloat(clean);
            return isNaN(num) ? 0 : num;
        };

        if (idxPriceCurrent !== -1 && row[idxPriceCurrent]) {
            priceCurrent = parseNum(row[idxPriceCurrent]);
        }

        if (idxPriceBase !== -1 && row[idxPriceBase]) {
            priceBase = parseNum(row[idxPriceBase]);
        }

        if (idxYield !== -1 && row[idxYield]) {
            dividendYield = parseNum(row[idxYield]);
        }

        if (idxReturn !== -1 && row[idxReturn]) {
            returnRate = parseNum(row[idxReturn]);
        } else if (priceBase > 0 && priceCurrent > 0) {
            returnRate = ((priceCurrent - priceBase) / priceBase) * 100;
        }

        if (priceCurrent === 0) {
             const nums = row.map((val, index) => ({ val: parseNum(val), index }))
                             .filter(({ val, index }) => !isNaN(val) && val > 0 && index !== idxCode);
             if (nums.length > 0) {
                 const possiblePrice = nums.find(n => n.val > 5); 
                 if (possiblePrice) priceCurrent = possiblePrice.val;
             }
        }

        etfs.push({
            code,
            name: name || code, 
            category,
            marketLabel, 
            priceBase: Number(priceBase.toFixed(2)),
            priceCurrent: Number(priceCurrent.toFixed(2)),
            dataDate: currentPriceDateLabel,
            dividendYield: Number(dividendYield.toFixed(2)),
            estYield: 0, 
            returnRate: Number(returnRate.toFixed(2)),
            totalReturn: Number(returnRate.toFixed(2)), 
            dividends: [] 
        });
    }
  }

  etfs.sort((a, b) => a.code.localeCompare(b.code));
  return etfs;
};

import React, { useState, useEffect, useCallback } from 'react';
import { EtfData, PortfolioItem } from './types';
import { convertToCsvUrl, parseEtfData, parseDividendData } from './utils/sheetHelpers';
import { analyzeSheets } from './services/geminiService';
import PerformanceView from './components/PerformanceView';
import PortfolioView from './components/PortfolioView';
import SheetConfigView from './components/SheetConfigView';
import { LayoutDashboard, PieChart, BrainCircuit, Bot, Megaphone, ArrowLeft, RotateCw, CheckCircle, AlertTriangle } from 'lucide-react';
import ReactMarkdown from 'react-markdown';

// Default URLs
const DEFAULT_URL_1 = "https://docs.google.com/spreadsheets/d/e/2PACX-1vT1Vpn2SSkcf7QLqoMoAsdyusxtydfgIQD8pyoV6XojGFnf0zGu_WWuRnI4N3U-Hu0iGRzTrR7N-OD9/pub?output=csv";
const DEFAULT_URL_2 = "https://docs.google.com/spreadsheets/d/e/2PACX-1vQdHAXZ0A9Uno0bztIwJbuYSmLUAXUR8SDeHn-Z6GWkuwx1PGkUppejuytX2fjB33kRO1hV35Ku31fl/pub?output=csv";

type Tab = 'performance' | 'portfolio' | 'planning' | 'diagnosis' | 'announcement';

const CACHE_KEY_DATA_1 = 'sheet_data_1';
const CACHE_KEY_DATA_2 = 'sheet_data_2';
const CACHE_KEY_TIME = 'sheet_last_fetch_time';
const CACHE_DURATION = 15 * 60 * 1000; // 15 分鐘 (毫秒)

const App: React.FC = () => {
  // App State
  const [isConfigured, setIsConfigured] = useState(false);
  const [activeTab, setActiveTab] = useState<Tab>('performance');

  // Data State
  const [etfs, setEtfs] = useState<EtfData[]>([]);
  const [portfolio, setPortfolio] = useState<PortfolioItem[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [rawData1, setRawData1] = useState("");
  const [rawData2, setRawData2] = useState("");
  const [lastUpdated, setLastUpdated] = useState<Date | null>(null);

  // AI State
  const [diagnosis, setDiagnosis] = useState("");
  const [isDiagnosing, setIsDiagnosing] = useState(false);

  // Notification State
  const [toast, setToast] = useState<{visible: boolean, message: string, type: 'success' | 'warning'}>({ visible: false, message: '', type: 'success' });

  // Helper to prevent infinite loading
  const fetchWithTimeout = async (url: string, timeout = 15000) => {
    const controller = new AbortController();
    const id = setTimeout(() => controller.abort(), timeout);
    try {
      const response = await fetch(url, { signal: controller.signal });
      clearTimeout(id);
      return response;
    } catch (error) {
      clearTimeout(id);
      throw error;
    }
  };

  const showToast = useCallback((message: string, type: 'success' | 'warning' = 'success') => {
    setToast({ visible: true, message, type });
    setTimeout(() => {
        setToast(prev => ({ ...prev, visible: false }));
    }, 3000); // 3秒後消失
  }, []);

  // 處理資料解析與狀態設定 (共用邏輯)
  const processData = useCallback((txt1: string, txt2: string) => {
      const parsedEtfs = parseEtfData(txt2);
      const dividendMap = parseDividendData(txt1);

      if (parsedEtfs.length === 0) {
           console.warn("No ETFs parsed.");
      }

      // Check if dividends are missing
      const totalDividends = Object.keys(dividendMap).length;
      if (parsedEtfs.length > 0 && totalDividends === 0) {
         showToast("警告：抓不到任何配息資料\n請檢查 Sheet 1 欄位名稱 (需包含：代號、配息金額、除息日)", 'warning');
      }

      const mergedEtfs = parsedEtfs.map(etf => ({
          ...etf,
          dividends: dividendMap[etf.code] || []
      }));

      setEtfs(mergedEtfs);
      setRawData1(txt1);
      setRawData2(txt2);
      setIsConfigured(true);
  }, [showToast]);

  // 應用程式啟動時，嘗試自動讀取快取
  useEffect(() => {
    const cachedData1 = localStorage.getItem(CACHE_KEY_DATA_1);
    const cachedData2 = localStorage.getItem(CACHE_KEY_DATA_2);
    const cachedTimeStr = localStorage.getItem(CACHE_KEY_TIME);

    if (cachedData1 && cachedData2 && cachedTimeStr) {
        try {
          console.log("Dev Mode: Auto-loading cached data...");
          processData(cachedData1, cachedData2);
          setLastUpdated(new Date(Number(cachedTimeStr)));
        } catch (e) {
          console.error("Cache corrupted, clearing...", e);
          localStorage.removeItem(CACHE_KEY_DATA_1);
          localStorage.removeItem(CACHE_KEY_DATA_2);
          localStorage.removeItem(CACHE_KEY_TIME);
        }
    }
  }, [processData]);

  const handleStartDataLoad = async (url1: string, url2: string, forceRefresh = false) => {
    setIsLoading(true);
    try {
        // 1. 檢查快取 (僅在非強制重新整理時檢查有效性)
        const cachedTimeStr = localStorage.getItem(CACHE_KEY_TIME);
        const cachedData1 = localStorage.getItem(CACHE_KEY_DATA_1);
        const cachedData2 = localStorage.getItem(CACHE_KEY_DATA_2);

        const now = Date.now();
        const isCacheValid = cachedTimeStr && (now - Number(cachedTimeStr) < CACHE_DURATION);

        // 如果不是強制重新整理，且快取有效，直接使用快取
        if (!forceRefresh && isCacheValid && cachedData1 && cachedData2) {
            console.log("Using Cached Data");
            try {
              processData(cachedData1, cachedData2);
              setLastUpdated(new Date(Number(cachedTimeStr)));
              setIsLoading(false);
              return;
            } catch (e) {
               console.warn("Cache parse failed, fetching fresh data.");
               // fall through to fetch
            }
        }

        // 2. 執行網路請求
        const csvUrl1 = convertToCsvUrl(url1);
        const csvUrl2 = convertToCsvUrl(url2);

        const [res1, res2] = await Promise.all([
            fetchWithTimeout(`https://api.allorigins.win/raw?url=${encodeURIComponent(csvUrl1)}`),
            fetchWithTimeout(`https://api.allorigins.win/raw?url=${encodeURIComponent(csvUrl2)}`)
        ]);

        if (!res1.ok || !res2.ok) throw new Error("無法讀取 Google Sheet (網路回應錯誤)");

        const txt1 = await res1.text();
        const txt2 = await res2.text();

        if (txt1.trim().startsWith("<!DOCTYPE") || txt2.trim().startsWith("<!DOCTYPE")) {
            throw new Error("抓取到的不是 CSV 資料，請檢查試算表權限是否已公開。");
        }

        // 3. 儲存快取
        localStorage.setItem(CACHE_KEY_DATA_1, txt1);
        localStorage.setItem(CACHE_KEY_DATA_2, txt2);
        localStorage.setItem(CACHE_KEY_TIME, now.toString());

        processData(txt1, txt2);
        setLastUpdated(new Date(now));

    } catch (err: any) {
        console.error("Failed to load data", err);
        let msg = "資料讀取失敗，請檢查網址或權限。";
        if (err.name === 'AbortError') {
            msg = "連線逾時，請檢查網路狀況。";
        } else if (err.message) {
            msg = err.message;
        }
        alert(msg);
        setIsConfigured(false);
    } finally {
        setIsLoading(false);
    }
  };

  const handleForceRefresh = () => {
      handleStartDataLoad(DEFAULT_URL_1, DEFAULT_URL_2, true);
  };

  const handleReset = () => {
      // 清除快取以便完全重設
      localStorage.removeItem(CACHE_KEY_DATA_1);
      localStorage.removeItem(CACHE_KEY_DATA_2);
      localStorage.removeItem(CACHE_KEY_TIME);

      setIsConfigured(false);
      setEtfs([]);
  };

  // 使用 useCallback 避免不必要的 re-render
  const handleAddToPortfolio = useCallback((etf: EtfData) => {
    const budget = 500000;
    const price = etf.priceCurrent || 10;
    const shares = Math.floor(budget / (price * 1000));
    const actualShares = Math.max(shares * 1000, 1000);

    const newItem: PortfolioItem = {
      id: Date.now().toString(),
      etf,
      shares: actualShares,
      avgCost: price,
      totalCost: actualShares * price,
      fee: Math.round(actualShares * price * 0.001425)
    };

    setPortfolio(prev => [...prev, newItem]);

    // 觸發彈跳視窗
    showToast(`成功加入！\n${etf.name}`, 'success');
  }, [showToast]);

  const handleRemoveFromPortfolio = (id: string) => {
    setPortfolio(prev => prev.filter(p => p.id !== id));
  };

  const handleAIDiagnosis = async () => {
    setIsDiagnosing(true);
    setDiagnosis("");
    try {
        await analyzeSheets(rawData1, rawData2, (text) => {
            setDiagnosis(prev => prev + text);
        });
    } catch(e) {
        setDiagnosis("AI 診斷連線失敗。");
    } finally {
        setIsDiagnosing(false);
    }
  };

  // --- Layout Components ---

  const renderContent = () => {
      if (!isConfigured) {
          return (
            <div className="h-full p-4 overflow-y-auto">
                <SheetConfigView 
                    defaultUrl1={DEFAULT_URL_1} 
                    defaultUrl2={DEFAULT_URL_2} 
                    onStart={(u1, u2) => handleStartDataLoad(u1, u2, true)} // 手動開始時強制刷新 (forceRefresh=true)
                    isLoading={isLoading}
                />
            </div>
          );
      }

      switch (activeTab) {
          case 'performance': 
            return (
                <PerformanceView 
                    etfs={etfs} 
                    onAddToPortfolio={handleAddToPortfolio} 
                    lastUpdated={lastUpdated}
                />
            );

          case 'portfolio': 
            return (
                <div className="h-full p-4 overflow-y-auto scrollbar-hide">
                    <PortfolioView portfolio={portfolio} onRemove={handleRemoveFromPortfolio} />
                </div>
            );

          case 'diagnosis': 
            return (
                <div className="h-full p-4 overflow-y-auto scrollbar-hide">
                    <div className="bg-white rounded-xl shadow-sm p-6 min-h-[400px]">
                        <div className="flex justify-between items-center mb-4 border-b border-slate-100 pb-3">
                            <h3 className="font-bold text-xl flex items-center gap-2 text-slate-800">
                                <Bot className="w-6 h-6 text-blue-900" /> AI 智能診斷
                            </h3>
                            <button 
                                onClick={handleAIDiagnosis}
                                disabled={isDiagnosing}
                                className="text-base bg-blue-900 text-white px-4 py-2 rounded-lg hover:bg-blue-800 disabled:opacity-50"
                            >
                                {isDiagnosing ? '診斷中...' : '開始診斷'}
                            </button>
                        </div>
                        <div className="prose prose-lg prose-slate text-lg leading-relaxed">
                            {diagnosis ? <ReactMarkdown>{diagnosis}</ReactMarkdown> : <p className="text-slate-400 text-lg">點擊上方按鈕，讓 AI 分析您的投資組合數據。</p>}
                        </div>
                    </div>
                </div>
            );

          default:
            return (
                <div className="h-full p-4 overflow-y-auto scrollbar-hide">
                    <div className="bg-white rounded-xl p-8 text-center text-slate-400 shadow-sm text-lg">
                        此功能開發中 (Mockup)
                    </div>
                </div>
            );
      }
  };

  return (
    <div className="flex flex-col h-screen bg-slate-50 font-sans text-slate-900 max-w-md mx-auto shadow-2xl overflow-hidden border-x border-slate-200 relative">

      <header className="bg-blue-900 text-white h-20 shrink-0 flex items-center justify-between px-4 shadow-md z-20">
        <div className="flex items-center gap-3">
            {isConfigured && (
                 <button onClick={handleReset} className="p-1 hover:bg-blue-800 rounded-full">
                    <ArrowLeft className="w-6 h-6" />
                 </button>
            )}
            <h1 className="text-xl font-bold tracking-wide">
                {isConfigured ? '投資助理' : '設定資料來源'}
            </h1>
        </div>
        <div className="flex items-center gap-2">
            {isConfigured && (
                <>
                    <button 
                        onClick={handleForceRefresh}
                        disabled={isLoading}
                        className={`p-2 rounded-full hover:bg-blue-800 transition-all text-blue-100 hover:text-white ${isLoading ? 'animate-spin' : ''}`}
                        title="更新資料"
                    >
                        <RotateCw className="w-5 h-5" />
                    </button>
                    <span className="text-sm bg-blue-800 px-2 py-1 rounded text-blue-200">測試版</span>
                </>
            )}
        </div>
      </header>

      <main className="flex-grow overflow-hidden bg-slate-50 relative">
        {renderContent()}
      </main>

      {/* Toast Notification Overlay */}
      {toast.visible && (
        <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 z-50 pointer-events-none">
            <div className={`
                backdrop-blur-md px-8 py-6 rounded-2xl shadow-2xl flex flex-col items-center gap-3 min-w-[240px] animate-[fadeIn_0.2s_ease-out]
                ${toast.type === 'warning' ? 'bg-yellow-900/90 text-white' : 'bg-black/85 text-white'}
            `}>
                {toast.type === 'warning' ? (
                    <AlertTriangle className="w-12 h-12 text-yellow-400" />
                ) : (
                    <CheckCircle className="w-12 h-12 text-green-400" />
                )}

                <span className="font-bold text-xl text-center whitespace-pre-wrap leading-relaxed">{toast.message}</span>

                {toast.type === 'success' && (
                    <span className="text-xs text-white/70">已加入自選清單</span>
                )}
            </div>
        </div>
      )}

      {isConfigured && (
          <nav className="bg-blue-900 text-white h-20 shrink-0 grid grid-cols-5 items-center text-center shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.1)] z-20">
            <button 
                onClick={() => setActiveTab('performance')}
                className={`flex flex-col items-center justify-center h-full gap-1 transition-colors ${activeTab === 'performance' ? 'text-yellow-400' : 'text-slate-300 hover:text-white'}`}
            >
                <LayoutDashboard className="w-6 h-6" />
                <span className="text-sm font-medium">績效</span>
            </button>
            <button 
                onClick={() => setActiveTab('portfolio')}
                className={`flex flex-col items-center justify-center h-full gap-1 transition-colors ${activeTab === 'portfolio' ? 'text-yellow-400' : 'text-slate-300 hover:text-white'}`}
            >
                <PieChart className="w-6 h-6" />
                <span className="text-sm font-medium">自組</span>
            </button>
            <button 
                onClick={() => setActiveTab('planning')}
                className={`flex flex-col items-center justify-center h-full gap-1 transition-colors ${activeTab === 'planning' ? 'text-yellow-400' : 'text-slate-300 hover:text-white'}`}
            >
                <BrainCircuit className="w-6 h-6" />
                <span className="text-sm font-medium">規劃</span>
            </button>
            <button 
                onClick={() => setActiveTab('diagnosis')}
                className={`flex flex-col items-center justify-center h-full gap-1 transition-colors ${activeTab === 'diagnosis' ? 'text-yellow-400' : 'text-slate-300 hover:text-white'}`}
            >
                <Bot className="w-6 h-6" />
                <span className="text-sm font-medium">診斷</span>
            </button>
            <button 
                onClick={() => setActiveTab('announcement')}
                className={`flex flex-col items-center justify-center h-full gap-1 transition-colors ${activeTab === 'announcement' ? 'text-yellow-400' : 'text-slate-300 hover:text-white'}`}
            >
                <Megaphone className="w-6 h-6" />
                <span className="text-sm font-medium">公告</span>
            </button>
          </nav>
      )}
    </div>
  );
};

