import React, { useState, useMemo } from 'react';
import { EtfData, CategoryKey, Dividend } from '../types';
import { ArrowUp, ArrowDown, Plus, TrendingUp, CircleAlert, ArrowLeft } from 'lucide-react';

interface Props {
  etfs: EtfData[];
  onAddToPortfolio: (etf: EtfData) => void;
  lastUpdated: Date | null;
}

// 定義分類配置 (兩字，無 "全部")
const CATEGORY_CONFIG: { key: CategoryKey; label: string }[] = [
  { key: 'AA', label: '季一' },
  { key: 'AB', label: '季二' },
  { key: 'AC', label: '季三' },
  { key: 'AD', label: '月配' },
  { key: 'AE', label: '債券' },
];

// 使用者指定的債券排序列表
const BOND_SPECIFIC_ORDER = [
  '00937B', '00772B', '00933B', '00773B', // 月配
  '00720B', '00725B', '00724B',           // 季一
  '00679B', '00761B', '00795B',           // 季二
  '00687B', '00751B', '00792B'            // 季三
];

// 輔助函式：判斷債券的配息週期類型 (用於顏色與詳細頁配息次數判斷)
const getBondType = (code: string): CategoryKey => {
    // 月配 (AD): 00937B, 00772B, 00933B, 00773B
    const monthlyBonds = ['00937B', '00772B', '00933B', '00773B'];
    if (monthlyBonds.some(b => code.includes(b))) return 'AD';

    // 季一 (AA): 00720B, 00725B, 00724B
    const groupQ1 = ['00720B', '00725B', '00724B'];
    if (groupQ1.some(b => code.includes(b))) return 'AA';

    // 季二 (AB): 00679B, 00761B, 00795B
    const groupQ2 = ['00679B', '00761B', '00795B'];
    if (groupQ2.some(b => code.includes(b))) return 'AB';

    // 季三 (AC): 00687B, 00751B, 00792B
    const groupQ3 = ['00687B', '00751B', '00792B'];
    if (groupQ3.some(b => code.includes(b))) return 'AC';

    // 其他未列出的債券預設歸類為季三
    return 'AC'; 
};

// Date helper for future check (handles YYYYMM)
const isFutureDate = (dateStr: string) => {
    if (!dateStr) return false;
    const cleanStr = dateStr.trim();
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    // YYYYMM
    if (/^\d{6}$/.test(cleanStr)) {
        const y = parseInt(cleanStr.substring(0, 4));
        const m = parseInt(cleanStr.substring(4, 6)) - 1;
        const d = new Date(y, m, 1);
        return d > today;
    }

    const standardDate = new Date(cleanStr.replace(/\./g, '/').replace(/-/g, '/'));
    if (isNaN(standardDate.getTime())) return false; 
    return standardDate > today;
};

const PerformanceView: React.FC<Props> = ({ etfs, onAddToPortfolio, lastUpdated }) => {
  const activeCatState = useState<CategoryKey>('AA');
  const [activeCat, setActiveCat] = activeCatState;
  const [selectedEtf, setSelectedEtf] = useState<EtfData | null>(null);

  // 1. 篩選與排序資料
  const filteredEtfs = useMemo(() => {
    // 先篩選出當前分類的資料
    let result = etfs.filter(e => e.category === activeCat);

    if (activeCat === 'AE') {
        // 債券特殊排序邏輯
        result.sort((a, b) => {
            const indexA = BOND_SPECIFIC_ORDER.indexOf(a.code);
            const indexB = BOND_SPECIFIC_ORDER.indexOf(b.code);

            if (indexA !== -1 && indexB !== -1) return indexA - indexB;
            if (indexA !== -1) return -1;
            if (indexB !== -1) return 1;
            return a.code.localeCompare(b.code);
        });
    } else {
        // 一般分類：依照股票代號排序
        result.sort((a, b) => a.code.localeCompare(b.code));
    }

    return result;
  }, [etfs, activeCat]);

  // 顯示用日期
  const displayDate = etfs.length > 0 && etfs[0].dataDate ? etfs[0].dataDate : '最新股價';

  // --- 顏色樣式邏輯 ---
  const getCardStyle = (etf: EtfData) => {
    let type: CategoryKey = 'AA';
    if (etf.category === 'AE') {
        type = getBondType(etf.code);
    } else {
        type = etf.category;
    }

    switch (type) {
        case 'AA': return 'bg-blue-50 border-blue-200';
        case 'AB': return 'bg-emerald-50 border-emerald-200';
        case 'AC': return 'bg-orange-50 border-orange-200';
        case 'AD': return 'bg-amber-50 border-amber-200';
        default: return 'bg-white border-slate-200';
    }
  };

  // --- 詳細資料頁面 (g. 詳細資料) ---
  if (selectedEtf) {
      // 判斷是否為月配：AD 類別 或 債券(AE)中的月配
      let resolvedCategory = selectedEtf.category;
      if (resolvedCategory === 'AE') {
          resolvedCategory = getBondType(selectedEtf.code);
      }

      const isMonthly = resolvedCategory === 'AD';
      const baseLimit = isMonthly ? 12 : 4; // 月配 12 筆，季配 4 筆

      // 排序：近 -> 遠 (b.date - a.date)
      const allSortedDividends = [...selectedEtf.dividends].sort((a, b) => {
           // String compare works for ISO YYYYMMDD or YYYY/MM/DD
           return b.date.localeCompare(a.date);
      });

      // h. 配息資料如有 預計配息資料 (未來日期) 筆數需 N+1 筆
      const hasFuture = allSortedDividends.length > 0 && isFutureDate(allSortedDividends[0].date);
      const displayCount = hasFuture ? baseLimit + 1 : baseLimit;

      const displayDividends = allSortedDividends.slice(0, displayCount);

      return (
          <div className={`flex flex-col h-full ${getCardStyle(selectedEtf).split(' ')[0]}`}>
              {/* Header: 詳細資料, 返回按鈕 */}
              <div className="h-16 shrink-0 flex items-center px-4 border-b border-black/5 gap-3 bg-white/60 backdrop-blur-sm">
                  <button onClick={() => setSelectedEtf(null)} className="p-2 hover:bg-black/5 rounded-full">
                      <ArrowLeft className="w-6 h-6 text-slate-700" />
                  </button>
                  <div className="flex-1">
                      <h2 className="text-lg font-bold text-slate-800">{selectedEtf.code} {selectedEtf.name}</h2>
                      <span className="text-xs text-slate-500">
                          {isMonthly ? '近 12 次配息 (月配)' : '近 4 次配息 (季配)'}
                      </span>
                  </div>
              </div>

              {/* Scrollable Content */}
              <div className="flex-1 overflow-y-auto p-4 scrollbar-hide">
                  <div className="bg-white/80 rounded-xl shadow-sm border border-black/5 overflow-hidden">
                    <table className="w-full text-left border-collapse">
                        <thead>
                            <tr className="text-slate-500 text-xs border-b border-slate-200/50">
                                <th className="py-2 px-4 font-medium">除息日 (近 → 遠)</th>
                                <th className="py-2 px-4 text-right font-medium">金額</th>
                                <th className="py-2 px-4 text-right font-medium">狀態</th>
                            </tr>
                        </thead>
                        <tbody>
                            {displayDividends.length > 0 ? (
                                displayDividends.map((div, idx) => {
                                    const isFuture = isFutureDate(div.date);
                                    // 未來配息資料: 底色為淡紅色 (bg-red-50)
                                    return (
                                        <tr key={idx} className={`border-b border-slate-100/50 ${isFuture ? 'bg-red-50' : ''}`}>
                                            <td className="py-3 px-4 text-slate-800 font-medium text-sm">{div.date}</td>
                                            <td className="py-3 px-4 text-right text-slate-800 font-bold text-sm">{div.amount}</td>
                                            <td className="py-3 px-4 text-right text-xs">
                                                {isFuture ? <span className="text-red-500 font-bold">預估/未除息</span> : <span className="text-slate-400">已除息</span>}
                                            </td>
                                        </tr>
                                    );
                                })
                            ) : (
                                <tr>
                                    <td colSpan={3} className="py-8 text-center text-slate-400 text-sm">無配息資料</td>
                                </tr>
                            )}
                        </tbody>
                    </table>
                  </div>

                  <div className="mt-6 p-4 bg-white/60 rounded-lg text-xs text-slate-500 leading-relaxed border border-black/5">
                      <p>※ 資料依日期由近至遠排序。</p>
                      <p>※ 紅色底色表示為系統判讀之「未來配息資料」或「預估值」。</p>
                  </div>
              </div>
          </div>
      );
  }

  // --- 列表清單頁面 (A1, A2 固定，A3 滑動) ---
  return (
    <div className="flex flex-col h-full bg-slate-50">

      {/* 頂部固定區域 (A1 + A2) */}
      <div className="shrink-0 z-10 bg-slate-50 shadow-sm border-b border-slate-200">

          {/* A1. "基準日" 與 "資料日期" */}
          <div className="h-16 bg-white px-4 flex justify-between items-center">
            {/* 左側: 基準日 */}
            <div className="flex items-baseline gap-2">
                <span className="text-[12px] text-slate-400 font-light">基準日 (Base)</span>
                <span className="text-[14px] text-slate-600 font-bold">2025/01/02</span>
            </div>

            {/* 右側: 資料日期 */}
            <div className="flex items-baseline gap-2">
              <span className="text-[12px] text-slate-400 font-light">資料日期</span>
              <span className="text-[14px] text-blue-900 font-bold">{displayDate}</span>
            </div>
          </div>

          {/* A2. 按鈕功能區 */}
          <div className="bg-white pb-2 px-2 pt-0 flex gap-2 overflow-x-auto scrollbar-hide">
            {CATEGORY_CONFIG.map((cat) => (
              <button
                key={cat.key}
                onClick={() => setActiveCat(cat.key)}
                className={`
                  flex-shrink-0 px-5 py-2 rounded-lg text-sm font-bold transition-all duration-200 whitespace-nowrap border
                  ${activeCat === cat.key 
                    ? 'bg-blue-900 text-white border-blue-900 shadow-sm' 
                    : 'bg-slate-50 text-slate-500 border-slate-200 hover:bg-slate-100'}
                `}
              >
                {cat.label}
              </button>
            ))}
          </div>
      </div>

      {/* A3. 表格內容: 可滑動區域 (Flex-1) */}
      <div className="flex-1 overflow-y-auto p-2 space-y-2 scrollbar-hide">
        {filteredEtfs.length > 0 ? (
            filteredEtfs.map((etf) => {
                // estYield logic handles in App.tsx (returns 0 if no future data)
                const estYieldDisplay = etf.estYield > 0 
                    ? `${etf.estYield}%` 
                    : <span className="text-slate-300">-</span>;

                const cardStyle = getCardStyle(etf);

                return (
                    <div key={etf.code} className={`rounded-lg p-2 shadow-sm border flex flex-col gap-0.5 ${cardStyle}`}>
                        {/* 第 1 行: 股票代碼 (20px 粗 藍色) / 名稱 (18px 細 灰色) */}
                        <div className="flex items-baseline gap-2 border-b border-black/5 pb-1 mb-0.5">
                            <span className="text-[20px] font-bold text-blue-800">{etf.code}</span>
                            <span className="text-[18px] font-light text-slate-500 truncate flex-1 leading-tight">{etf.name}</span>
                            <span className={`text-[10px] px-1.5 py-0 rounded border bg-white/50 border-black/10 text-slate-500`}>
                                {etf.marketLabel}
                            </span>
                        </div>

                        {/* 第 2 行: 最近股價, 殖利率, 報酬率, [按鈕: + 自組月配] */}
                        {/* 標題 10px 細 / 內容 18px 粗 */}
                        <div className="grid grid-cols-4 items-center gap-1 leading-tight">
                            <div className="flex flex-col">
                                <span className="text-[10px] font-light text-slate-600">最近股價</span>
                                <span className="text-[18px] font-bold text-slate-900">{etf.priceCurrent}</span>
                            </div>
                            <div className="flex flex-col text-right">
                                <span className="text-[10px] font-light text-slate-600">殖利率</span>
                                <span className="text-[18px] font-bold text-slate-900">{etf.dividendYield}%</span>
                            </div>
                            <div className="flex flex-col text-right">
                                <span className="text-[10px] font-light text-slate-600">報酬率</span>
                                <span className={`text-[18px] font-bold ${etf.returnRate >= 0 ? 'text-red-700' : 'text-green-700'}`}>
                                    {etf.returnRate}%
                                </span>
                            </div>
                            <div className="text-right flex justify-end">
                                {/* 按鈕: 自組月配 (+) */}
                                <button 
                                    onClick={(e) => {
                                        e.stopPropagation();
                                        e.preventDefault();
                                        onAddToPortfolio(etf);
                                    }}
                                    className="w-8 h-8 flex items-center justify-center bg-emerald-100/50 text-emerald-800 rounded-full hover:bg-emerald-200 transition-colors border border-emerald-200/50 shadow-sm"
                                >
                                    <Plus className="w-5 h-5" />
                                </button>
                            </div>
                        </div>

                        {/* 第 3 行: 起始股價, 預估殖利率, 含息報酬, [按鈕: CircleAlert 詳細資料] */}
                        {/* 標題 10px 細 / 內容 18px 細字 (更改部分) */}
                        <div className="grid grid-cols-4 items-center gap-1 bg-white/40 -mx-2 px-2 py-1 rounded-b-lg mt-0.5 leading-tight">
                            <div className="flex flex-col">
                                <span className="text-[10px] font-light text-slate-600">起始股價</span>
                                <span className="text-[18px] font-light text-slate-900">{etf.priceBase}</span>
                            </div>
                            <div className="flex flex-col text-right">
                                <span className="text-[10px] font-light text-slate-600">預估殖利率</span>
                                <span className="text-[18px] font-light text-slate-900">{estYieldDisplay}</span>
                            </div>
                            <div className="flex flex-col text-right">
                                <span className="text-[10px] font-light text-slate-600">含息報酬</span>
                                <span className={`text-[18px] font-light ${etf.totalReturn >= 0 ? 'text-red-700' : 'text-green-700'}`}>
                                    {etf.totalReturn}%
                                </span>
                            </div>
                            <div className="text-right flex justify-end">
                                {/* 按鈕: 詳細資料 (CircleAlert) */}
                                <button 
                                    onClick={(e) => {
                                        e.stopPropagation();
                                        e.preventDefault();
                                        setSelectedEtf(etf);
                                    }}
                                    className="w-8 h-8 flex items-center justify-center bg-white/60 text-slate-700 rounded-lg hover:bg-white hover:text-black transition-colors border border-black/5"
                                >
                                    <CircleAlert className="w-5 h-5" />
                                </button>
                            </div>
                        </div>
                    </div>
                );
            })
        ) : (
            <div className="py-12 text-center text-slate-400 text-sm">
                目前分類無資料
            </div>
        )}
      </div>
    </div>
  );
};

export default PerformanceView;

import React, { useState, useEffect, useCallback } from 'react';
import { EtfData, PortfolioItem, Dividend, CategoryKey } from './types';
import { convertToCsvUrl, parseEtfData, parseDividendData } from './utils/sheetHelpers';
import { analyzeSheets } from './services/geminiService';
import PerformanceView from './components/PerformanceView';
import PortfolioView from './components/PortfolioView';
import SheetConfigView from './components/SheetConfigView';
import { LayoutDashboard, PieChart, BrainCircuit, Bot, Megaphone, ArrowLeft, RotateCw, CheckCircle, AlertTriangle, Loader2 } from 'lucide-react';
import ReactMarkdown from 'react-markdown';

// Default URLs (Updated by User Request)
const DEFAULT_URL_1 = "https://docs.google.com/spreadsheets/d/e/2PACX-1vT1Vpn2SSkcf7QLqoMoAsdyusxtydfgIQD8pyoV6XojGFnf0zGu_WWuRnI4N3U-Hu0iGRzTrR7N-OD9/pub?output=csv";
const DEFAULT_URL_2 = "https://docs.google.com/spreadsheets/d/e/2PACX-1vQdHAXZ0A9Uno0bztIwJbuYSmLUAXUR8SDeHn-Z6GWkuwx1PGkUppejuytX2fjB33kRO1hV35Ku31fl/pub?output=csv";

// Base Date for calculations (2025/01/02)
const BASE_DATE_STR = "2025/01/02";

type Tab = 'performance' | 'portfolio' | 'planning' | 'diagnosis' | 'announcement';

const CACHE_KEY_DATA_1 = 'sheet_data_1_v6'; // Updated version key
const CACHE_KEY_DATA_2 = 'sheet_data_2_v6'; // Updated version key
const CACHE_KEY_TIME = 'sheet_last_fetch_time_v6';
const CACHE_DURATION = 15 * 60 * 1000; // 15 分鐘 (毫秒)

const App: React.FC = () => {
  // App State
  const [isConfigured, setIsConfigured] = useState(false);
  const [activeTab, setActiveTab] = useState<Tab>('performance');

  // Data State
  const [etfs, setEtfs] = useState<EtfData[]>([]);
  const [portfolio, setPortfolio] = useState<PortfolioItem[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [rawData1, setRawData1] = useState("");
  const [rawData2, setRawData2] = useState("");
  const [lastUpdated, setLastUpdated] = useState<Date | null>(null);

  // AI State
  const [diagnosis, setDiagnosis] = useState("");
  const [isDiagnosing, setIsDiagnosing] = useState(false);

  // Notification State
  const [toast, setToast] = useState<{visible: boolean, message: string, type: 'success' | 'warning'}>({ visible: false, message: '', type: 'success' });

  // Helper to prevent infinite loading
  const fetchWithTimeout = async (url: string, timeout = 10000) => {
    const controller = new AbortController();
    const id = setTimeout(() => controller.abort(), timeout);
    try {
      const response = await fetch(url, { signal: controller.signal });
      clearTimeout(id);
      return response;
    } catch (error) {
      clearTimeout(id);
      throw error;
    }
  };

  // Smart Fetch: Tries Direct first, then Proxy
  const smartFetch = async (url: string): Promise<string> => {
      // 1. Try Direct Fetch
      try {
          const res = await fetchWithTimeout(url, 8000);
          if (res.ok) {
              return await res.text();
          }
      } catch (e) {
          console.warn(`Direct fetch failed for ${url}, trying proxy...`, e);
      }

      // 2. Try Proxy (AllOrigins)
      try {
          const proxyUrl = `https://api.allorigins.win/raw?url=${encodeURIComponent(url)}`;
          const res = await fetchWithTimeout(proxyUrl, 15000);
          if (res.ok) {
              return await res.text();
          }
      } catch (e) {
          console.warn(`Proxy fetch failed for ${url}`, e);
      }

      throw new Error("無法讀取資料，請檢查網址權限或網路連線。");
  };

  const showToast = useCallback((message: string, type: 'success' | 'warning' = 'success') => {
    setToast({ visible: true, message, type });
    setTimeout(() => {
        setToast(prev => ({ ...prev, visible: false }));
    }, 3000); // 3秒後消失
  }, []);

  // --- Date Parsing Helper ---
  // Handles: "202601" (YYYYMM), "2024/01/01", "2024-01-01"
  const parseSmartDate = (dateStr: string): Date | null => {
      if (!dateStr) return null;
      const cleanStr = dateStr.trim();

      // Handle YYYYMM (6 digits)
      if (/^\d{6}$/.test(cleanStr)) {
          const y = parseInt(cleanStr.substring(0, 4));
          const m = parseInt(cleanStr.substring(4, 6)) - 1; // Month is 0-indexed
          return new Date(y, m, 1); // Assume 1st of the month
      }

      // Handle Standard Date
      const standardDate = new Date(cleanStr.replace(/\./g, '/').replace(/-/g, '/'));
      if (!isNaN(standardDate.getTime())) {
          return standardDate;
      }

      return null;
  };

  // --- Yield Calculation Logic ---

  // 1. TTM Yield (Past 365 Days)
  const calculateAnnualYield = (dividends: Dividend[], currentPrice: number): number => {
      if (!currentPrice || currentPrice === 0) return 0;
      if (!dividends || dividends.length === 0) return 0;

      const today = new Date();
      today.setHours(0,0,0,0);
      const oneYearAgo = new Date(today);
      oneYearAgo.setFullYear(today.getFullYear() - 1);

      // Filter: Date >= One Year Ago AND Date <= Today (Exclude Future)
      const ttmDividends = dividends.filter(d => {
          const dDate = parseSmartDate(d.date);
          if (!dDate) return false;
          return dDate >= oneYearAgo && dDate <= today; 
      });

      const totalAmount = ttmDividends.reduce((sum, d) => sum + d.amount, 0);
      return parseFloat(((totalAmount / currentPrice) * 100).toFixed(2));
  };

  // 2. Estimated Yield (Triggered only if FUTURE data exists)
  const calculateEstimatedYield = (dividends: Dividend[], currentPrice: number, category: CategoryKey, code: string): number => {
      if (!currentPrice || currentPrice === 0) return 0;
      if (!dividends || dividends.length === 0) return 0;

      // Sort Descending (Newest First)
      const sortedDivs = [...dividends].sort((a, b) => {
          const dA = parseSmartDate(a.date);
          const dB = parseSmartDate(b.date);
          return (dB?.getTime() || 0) - (dA?.getTime() || 0);
      });

      const latestDiv = sortedDivs[0];
      const latestDate = parseSmartDate(latestDiv.date);
      const today = new Date();
      today.setHours(0,0,0,0);

      // Rule: "有未來配息之料才計算 , 否則 輸入 空值 (0)"
      if (!latestDate || latestDate <= today) {
          return 0;
      }

      // Determine Target Count (4 for Quarterly, 12 for Monthly)
      let targetCount = 4; // Default Quarterly

      // Identify Monthly
      const isMonthlyBond = ['00937B', '00772B', '00933B', '00773B'].some(c => code.includes(c));
      if (category === 'AD' || isMonthlyBond) {
          targetCount = 12;
      }

      // Sum the latest N dividends (including the future one)
      const targetDivs = sortedDivs.slice(0, targetCount);
      const totalEstimatedAmount = targetDivs.reduce((sum, d) => sum + d.amount, 0);

      return parseFloat(((totalEstimatedAmount / currentPrice) * 100).toFixed(2));
  };

  // 處理資料解析與狀態設定 (共用邏輯)
  const processData = useCallback((txt1: string, txt2: string) => {
      try {
          const parsedEtfs = parseEtfData(txt2);
          const dividendMap = parseDividendData(txt1);
          const baseDate = new Date(BASE_DATE_STR);
          const today = new Date();
          today.setHours(0,0,0,0);

          if (parsedEtfs.length === 0) {
              console.warn("No ETFs parsed.");
          }

          // Check if dividends are missing
          const totalDividends = Object.keys(dividendMap).length;
          if (parsedEtfs.length > 0 && totalDividends === 0) {
            showToast("警告：抓不到配息資料\n請確認表單欄位名稱包含：「ETF 代碼」、「除息金額」、「除息日期」", 'warning');
          }

          const mergedEtfs = parsedEtfs.map(etf => {
              const divs = dividendMap[etf.code] || [];

              // 1. Calculate TTM Yield (Actual Past Year)
              let finalYield = etf.dividendYield;
              const calculatedYield = calculateAnnualYield(divs, etf.priceCurrent);
              if (calculatedYield > 0) {
                  finalYield = calculatedYield;
              }

              // 2. Calculate Estimated Yield (Future Based)
              const estYield = calculateEstimatedYield(divs, etf.priceCurrent, etf.category, etf.code);

              // 3. Calculate Total Return (含息報酬率)
              // 邏輯: (最新股價 + 基準日後的配息總和 - 基準股價) / 基準股價
              let finalTotalReturn = etf.totalReturn;
              if (etf.priceBase > 0) {
                  const dividendsSinceBase = divs.filter(d => {
                      const dDate = parseSmartDate(d.date);
                      // 條件：配息日在基準日之後，且不晚於今天(排除未來)
                      return dDate && dDate >= baseDate && dDate <= today;
                  }).reduce((sum, d) => sum + d.amount, 0);

                  finalTotalReturn = parseFloat((((etf.priceCurrent + dividendsSinceBase - etf.priceBase) / etf.priceBase) * 100).toFixed(2));
              }

              return {
                ...etf,
                dividends: divs,
                dividendYield: finalYield,
                estYield: estYield,
                totalReturn: finalTotalReturn
              };
          });

          setEtfs(mergedEtfs);
          setRawData1(txt1);
          setRawData2(txt2);
          setIsConfigured(true);
      } catch (e) {
          console.error("Error processing data:", e);
          alert("資料解析發生錯誤，請檢查欄位格式。");
          setIsConfigured(false);
      }
  }, [showToast]);

  const handleStartDataLoad = useCallback(async (url1: string, url2: string, forceRefresh = false) => {
    setIsLoading(true);
    try {
        // 1. 檢查快取 (僅在非強制重新整理時檢查有效性)
        const cachedTimeStr = localStorage.getItem(CACHE_KEY_TIME);
        const cachedData1 = localStorage.getItem(CACHE_KEY_DATA_1);
        const cachedData2 = localStorage.getItem(CACHE_KEY_DATA_2);

        const now = Date.now();
        const isCacheValid = cachedTimeStr && (now - Number(cachedTimeStr) < CACHE_DURATION);

        // 如果不是強制重新整理，且快取有效，直接使用快取
        if (!forceRefresh && isCacheValid && cachedData1 && cachedData2) {
            console.log("Using Cached Data");
            try {
              processData(cachedData1, cachedData2);
              setLastUpdated(new Date(Number(cachedTimeStr)));
              setIsLoading(false);
              return;
            } catch (e) {
               console.warn("Cache parse failed, fetching fresh data.");
               // fall through to fetch
            }
        }

        // 2. 執行網路請求 (Smart Fetch)
        const csvUrl1 = convertToCsvUrl(url1);
        const csvUrl2 = convertToCsvUrl(url2);

        const [txt1, txt2] = await Promise.all([
            smartFetch(csvUrl1),
            smartFetch(csvUrl2)
        ]);

        if (txt1.trim().startsWith("<!DOCTYPE") || txt2.trim().startsWith("<!DOCTYPE")) {
            throw new Error("抓取到的不是 CSV 資料，請檢查試算表權限是否已公開。");
        }

        // 3. 儲存快取
        localStorage.setItem(CACHE_KEY_DATA_1, txt1);
        localStorage.setItem(CACHE_KEY_DATA_2, txt2);
        localStorage.setItem(CACHE_KEY_TIME, now.toString());

        processData(txt1, txt2);
        setLastUpdated(new Date(now));

    } catch (err: any) {
        console.error("Failed to load data", err);
        let msg = "資料讀取失敗，請檢查網址或權限。";
        if (err.name === 'AbortError') {
            msg = "連線逾時，請檢查網路狀況。";
        } else if (err.message) {
            msg = err.message;
        }
        alert(msg);
        setIsConfigured(false);
    } finally {
        setIsLoading(false);
    }
  }, [processData]);

  // 應用程式啟動時：1. 嘗試快取 2. 若無快取則自動讀取預設網址
  useEffect(() => {
    const cachedData1 = localStorage.getItem(CACHE_KEY_DATA_1);
    const cachedData2 = localStorage.getItem(CACHE_KEY_DATA_2);
    const cachedTimeStr = localStorage.getItem(CACHE_KEY_TIME);

    if (cachedData1 && cachedData2 && cachedTimeStr) {
        // 有快取：直接載入
        console.log("Auto-loading cached data on mount...");
        try {
            processData(cachedData1, cachedData2);
            setLastUpdated(new Date(Number(cachedTimeStr)));
        } catch(e) {
            handleStartDataLoad(DEFAULT_URL_1, DEFAULT_URL_2, true);
        }
    } else {
        // 無快取：自動執行第一次讀取 (Auto Start)
        console.log("No cache found, auto-starting data load...");
        handleStartDataLoad(DEFAULT_URL_1, DEFAULT_URL_2, true);
    }
  }, [processData, handleStartDataLoad]); // Added dependency to suppress lint warning, using useCallback to stabilize

  const handleForceRefresh = () => {
      handleStartDataLoad(DEFAULT_URL_1, DEFAULT_URL_2, true);
  };

  const handleReset = () => {
      // 僅切換回設定模式，不一定要刪除快取，讓使用者可以修改網址
      // 但為了體驗一致，這裡暫時不刪資料，只是切換 UI 狀態
      setIsConfigured(false);
  };

  const handleAddToPortfolio = useCallback((etf: EtfData) => {
    const budget = 500000;
    const price = etf.priceCurrent || 10;
    const shares = Math.floor(budget / (price * 1000));
    const actualShares = Math.max(shares * 1000, 1000);

    const newItem: PortfolioItem = {
      id: Date.now().toString(),
      etf,
      shares: actualShares,
      avgCost: price,
      totalCost: actualShares * price,
