        category: CategoryKey;
        priceCurrent: number;
        date: string;
        amount: number;
        singleYield: string;
    }> = [];

    etfs.forEach(etf => {
        etf.dividends.forEach(div => {
            if (isFutureDate(div.date)) {
                // 計算單次殖利率
                const yieldVal = etf.priceCurrent > 0 
                    ? ((div.amount / etf.priceCurrent) * 100).toFixed(2) 
