                      </div>
                  ))}
              </div>
          ) : (
              <div className="h-full flex flex-col items-center justify-center text-slate-400 space-y-4">
                  <div className="bg-slate-100 p-6 rounded-full">
                    <Calendar className="w-12 h-12 text-slate-300" />
                  </div>
                  <p>目前此分類無即將配息資料</p>
              </div>
          )}
      </div>
    </div>
  );
};

