                                                        <td colSpan={5} className="p-4 block md:table-cell">
                                                            <div className="flex flex-col gap-4">
                                                                <div className="flex justify-between items-center pb-2 border-b border-orange-100 mb-1">
                                                                    <span className="text-sm font-bold text-orange-800">編輯交易紀錄</span>
                                                                </div>
                                                                {/* Row 1: Label 12px Light, Input 16px Bold */}
                                                                <div className="grid grid-cols-2 gap-4">
                                                                    <div className="flex flex-col gap-1.5">
                                                                        <label className="text-[12px] font-light text-slate-500">日期</label>
                                                                        <input 
                                                                            type="text" value={editForm.date} onChange={(e) => handleEditChange('date', e.target.value)}
                                                                            className="text-[16px] font-bold text-slate-900 border border-slate-300 rounded-lg px-3 py-2 w-full focus:outline-none focus:ring-2 focus:ring-orange-500/20 focus:border-orange-500 bg-white" placeholder="YYYY/MM/DD"
                                                                        />
                                                                    </div>
                                                                    <div className="flex flex-col gap-1.5">
                                                                        <label className="text-[12px] font-light text-slate-500">張數</label>
                                                                        <input 
                                                                            type="number" value={editForm.shares} onChange={(e) => handleEditChange('shares', e.target.value)}
                                                                            className="text-[16px] font-bold text-slate-900 border border-slate-300 rounded-lg px-3 py-2 w-full text-right focus:outline-none focus:ring-2 focus:ring-orange-500/20 focus:border-orange-500 bg-white"
                                                                        />
