};

export default App;

import React, { useState } from 'react';
import { PortfolioItem, Transaction } from '../types';
import { Trash2, Wallet, ChevronDown, ChevronUp, Edit3, Save, Plus, Calculator, TrendingUp } from 'lucide-react';

interface Props {
  portfolio: PortfolioItem[];
  onUpdateTransaction: (etfCode: string, tx: Transaction) => void;
  onDeleteTransaction: (etfCode: string, txId: string) => void;
  onAddTransaction: (etfCode: string, tx: Transaction) => void;
}

const PortfolioView: React.FC<Props> = ({ portfolio, onUpdateTransaction, onDeleteTransaction, onAddTransaction }) => {
  // UI State
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [editingTxId, setEditingTxId] = useState<string | null>(null);
  const [addingToId, setAddingToId] = useState<string | null>(null);

  // Forms
  const [editForm, setEditForm] = useState<Transaction | null>(null);
  const [addForm, setAddForm] = useState<Transaction | null>(null);

  // Toggle Expansion
  const toggleExpand = (id: string) => {
    if (expandedId === id) {
      setExpandedId(null);
    } else {
      setExpandedId(id);
    }
    // Close any active edit/add when switching rows
    setEditingTxId(null);
    setEditForm(null);
    setAddingToId(null);
    setAddForm(null);
  };

  // --- Add Mode ---
  const startAdd = (item: PortfolioItem) => {
      const today = new Date().toISOString().split('T')[0].replace(/-/g, '/');
      const defaultPrice = item.etf.priceCurrent || 0;
      setAddingToId(item.id);
      setAddForm({
          id: Date.now().toString(),
          date: today,
          shares: 1000,
          price: defaultPrice,
          totalAmount: 1000 * defaultPrice
      });
      // Ensure row is expanded
      setExpandedId(item.id);
      setEditingTxId(null);
  };

  const handleAddChange = (field: keyof Transaction, value: string | number) => {
      if (!addForm) return;
      let newVal = value;
      if (field === 'price' || field === 'shares' || field === 'totalAmount') {
           newVal = Number(value);
      }
      const updated = { ...addForm, [field]: newVal };
      if (field === 'shares' || field === 'price') {
          updated.totalAmount = Number(updated.shares) * Number(updated.price);
      }
      setAddForm(updated);
  };

  const saveAdd = (etfCode: string) => {
      if (addForm) {
          onAddTransaction(etfCode, addForm);
          setAddingToId(null);
          setAddForm(null);
      }
  };

  const cancelAdd = () => {
      setAddingToId(null);
      setAddForm(null);
  };

  // --- Edit Mode ---
  const startEdit = (tx: Transaction) => {
    setEditingTxId(tx.id);
    setEditForm({ ...tx });
    setAddingToId(null); // Close add mode if open
  };

  const handleEditChange = (field: keyof Transaction, value: string | number) => {
    if (!editForm) return;
    let newVal = value;
    if (field === 'price' || field === 'shares' || field === 'totalAmount') {
         newVal = Number(value);
    }
    const updated = { ...editForm, [field]: newVal };
    if (field === 'shares' || field === 'price') {
        updated.totalAmount = Number(updated.shares) * Number(updated.price);
    }
    setEditForm(updated);
  };

  const saveEdit = (etfCode: string) => {
      if (editForm) {
          onUpdateTransaction(etfCode, editForm);
          setEditingTxId(null);
          setEditForm(null);
      }
  };

  const cancelEdit = () => {
      setEditingTxId(null);
      setEditForm(null);
  };

  // --- Aggregates ---
  const grandTotalCost = portfolio.reduce((sum, item) => {
      return sum + item.transactions.reduce((tSum, tx) => tSum + tx.totalAmount, 0);
  }, 0);

  const totalMonthlyIncome = portfolio.reduce((sum, item) => {
      const totalShares = item.transactions.reduce((s, tx) => s + tx.shares, 0);
      return sum + (item.etf.priceCurrent * totalShares * item.etf.dividendYield / 100 / 12); 
  }, 0);

  const estimatedMonthlyGrowth = portfolio.reduce((sum, item) => {
       const itemCost = item.transactions.reduce((tSum, tx) => tSum + tx.totalAmount, 0);
       return sum + (itemCost * (item.etf.returnRate / 100 / 12));
  }, 0);


  return (
    <div className="flex flex-col h-full bg-slate-50">

      {/* A1: Statistics (Fixed at Top) */}
      <div className="shrink-0 p-4 pb-2 z-10 bg-slate-50 border-b border-slate-200/50">
        <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
            <div className="bg-slate-50 px-4 py-3 border-b border-slate-100 flex items-center gap-2">
                <Calculator className="w-4 h-4 text-blue-900" />
                <span className="font-bold text-slate-700 text-sm">統計畫面</span>
            </div>
            <div className="p-4 grid grid-cols-2 gap-4">
                <div className="flex flex-col gap-1">
                    <span className="text-xs text-slate-500">每月預估股息</span>
                    <span className="text-2xl font-bold text-yellow-600 font-mono tracking-tight">
                        ${Math.round(totalMonthlyIncome).toLocaleString()}
                    </span>
                </div>
                <div className="flex flex-col gap-1">
                    <span className="text-xs text-slate-500">每月預估績效成長</span>
                    <div className="flex items-center gap-1">
                        <TrendingUp className={`w-4 h-4 ${estimatedMonthlyGrowth >= 0 ? 'text-red-500' : 'text-green-500'}`} />
                        <span className={`text-2xl font-bold font-mono tracking-tight ${estimatedMonthlyGrowth >= 0 ? 'text-red-600' : 'text-green-600'}`}>
                            ${Math.round(Math.abs(estimatedMonthlyGrowth)).toLocaleString()}
                        </span>
                    </div>
                </div>
                <div className="col-span-2 pt-2 border-t border-slate-100 flex justify-between items-baseline">
                    <span className="text-xs text-slate-400">總投資金額</span>
                    <span className="text-lg font-bold text-slate-800 font-mono">
                        ${grandTotalCost.toLocaleString()}
                    </span>
                </div>
            </div>
        </div>
      </div>

      {/* A2: Holdings List (Scrollable Area) */}
      <div className="flex-1 overflow-y-auto p-4 pt-2 scrollbar-hide">
          {portfolio.length > 0 ? (
            <div className="space-y-3 pb-20">
                {portfolio.map((item) => {
                    // Aggregates for Master Row
                    const totalShares = item.transactions.reduce((sum, tx) => sum + tx.shares, 0);
                    const totalCost = item.transactions.reduce((sum, tx) => sum + tx.totalAmount, 0);
                    const avgCost = totalShares > 0 ? (totalCost / totalShares).toFixed(2) : 0;

                    const isExpanded = expandedId === item.id;

                    return (
                        <div key={item.id} className={`bg-white rounded-xl shadow-sm border transition-all ${isExpanded ? 'border-blue-300 ring-1 ring-blue-100' : 'border-slate-200'}`}>

                            {/* A. 母表 (Master Row) */}
                            <div 
                                onClick={() => toggleExpand(item.id)}
                                className="p-4 flex flex-col gap-3 cursor-pointer active:bg-slate-50"
                            >
                                {/* Line 1: Code (Blue 20px Bold), Name (Gray 18px Light), Add Button */}
                                <div className="flex justify-between items-center border-b border-slate-100 pb-2">
                                    <div className="flex items-baseline gap-2 overflow-hidden">
                                        <span className="text-[20px] font-bold text-blue-900">{item.id}</span>
                                        <span className="text-[18px] font-light text-slate-500 truncate">{item.etf.name}</span>
                                    </div>
                                    <button 
                                        onClick={(e) => { e.stopPropagation(); startAdd(item); }}
                                        className="flex items-center gap-1 bg-blue-100 text-blue-800 px-3 py-1.5 rounded-full hover:bg-blue-200 transition-colors shadow-sm"
                                    >
                                        <Plus className="w-4 h-4" />
                                        <span className="text-xs font-bold">新增</span>
                                    </button>
                                </div>

                                {/* Line 2: Stats (Label 12px Light, Value 14px Bold) */}
                                <div className="grid grid-cols-3 gap-2">
                                    <div className="flex flex-col">
                                        <span className="text-[12px] font-light text-slate-400">累計張數</span>
                                        <span className="text-[14px] font-bold text-slate-800">{totalShares.toLocaleString()}</span>
                                    </div>
                                    <div className="flex flex-col text-center">
                                        <span className="text-[12px] font-light text-slate-400">平均成本</span>
                                        <span className="text-[14px] font-bold text-slate-800">{avgCost}</span>
                                    </div>
                                    <div className="flex flex-col text-right">
                                        <span className="text-[12px] font-light text-slate-400">投資金額總計</span>
                                        <span className="text-[14px] font-bold text-slate-800">${totalCost.toLocaleString()}</span>
                                    </div>
                                </div>
                            </div>

                            {/* B. 子表 (Child Table - Transactions) */}
                            {isExpanded && (
                                <div className="border-t border-slate-100 bg-slate-50/50 p-3 rounded-b-xl">

                                    {/* 1. Add Form (Uses same layout as Edit) */}
                                    {addingToId === item.id && addForm && (
                                        <div className="bg-blue-50/50 rounded-lg p-4 mb-4 border border-blue-200 shadow-sm">
                                            <div className="flex justify-between items-center pb-2 border-b border-blue-100 mb-2">
                                                <span className="text-sm font-bold text-blue-800 flex items-center gap-1">
                                                    <Plus className="w-4 h-4" /> 新增交易
                                                </span>
                                            </div>
                                            {/* 2-Row Layout: Row 1 (Date, Total), Row 2 (Shares, Price) */}
                                            <div className="grid grid-cols-2 gap-4 mb-4">
                                                {/* Row 1 */}
                                                <div className="flex flex-col gap-1">
                                                    <label className="text-[12px] font-light text-slate-500">日期</label>
                                                    <input 
                                                        type="text" value={addForm.date} onChange={(e) => handleAddChange('date', e.target.value)}
                                                        className="text-[16px] font-bold text-slate-900 border border-slate-300 rounded-lg px-3 py-2 w-full bg-white focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500" placeholder="YYYY/MM/DD"
                                                    />
                                                </div>
                                                <div className="flex flex-col gap-1">
                                                    <label className="text-[12px] font-light text-slate-500">成交總價</label>
                                                    <input 
                                                        type="number" value={addForm.totalAmount} onChange={(e) => handleAddChange('totalAmount', e.target.value)}
                                                        className="text-[16px] font-bold text-slate-900 border border-slate-300 rounded-lg px-3 py-2 w-full text-right bg-slate-100"
                                                    />
                                                </div>

                                                {/* Row 2 */}
                                                <div className="flex flex-col gap-1">
                                                    <label className="text-[12px] font-light text-slate-500">張數</label>
                                                    <input 
                                                        type="number" value={addForm.shares} onChange={(e) => handleAddChange('shares', e.target.value)}
                                                        className="text-[16px] font-bold text-slate-900 border border-slate-300 rounded-lg px-3 py-2 w-full text-right bg-white focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500"
