                                                </div>
                                                <div className="flex flex-col gap-1">
                                                    <label className="text-[12px] font-light text-slate-500">單價</label>
                                                    <input 
                                                        type="number" value={addForm.price} onChange={(e) => handleAddChange('price', e.target.value)}
                                                        className="text-[16px] font-bold text-slate-900 border border-slate-300 rounded-lg px-3 py-2 w-full text-right bg-white focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500"
                                                    />
                                                </div>
                                            </div>
                                            <div className="flex gap-3 justify-end">
                                                <button onClick={cancelAdd} className="px-4 py-2 text-slate-500 text-sm font-bold bg-white border border-slate-200 rounded-lg">取消</button>
                                                <button onClick={() => saveAdd(item.id)} className="px-4 py-2 text-white text-sm font-bold bg-blue-600 rounded-lg shadow-sm hover:bg-blue-700">儲存</button>
                                            </div>
                                        </div>
                                    )}

                                    <table className="w-full text-left border-collapse">
                                        {/* Header: 12px Light Gray */}
                                        {!editingTxId && (
                                            <thead>
                                                <tr className="text-[12px] font-light text-slate-400 border-b border-slate-200">
                                                    <th className="pb-2 pl-1 font-light">日期</th>
                                                    <th className="pb-2 text-right font-light">張數</th>
                                                    <th className="pb-2 text-right font-light">單價</th>
                                                    <th className="pb-2 text-right font-light">成交總價</th>
                                                    <th className="pb-2 text-right w-16 font-light">操作</th>
                                                </tr>
                                            </thead>
                                        )}
                                        <tbody className="text-sm">
                                            {item.transactions.map((tx) => {
                                                const isEditing = editingTxId === tx.id;

                                                if (isEditing && editForm) {
                                                    // --- Edit Mode (2-Row Layout) ---
                                                    return (
                                                        <tr key={tx.id} className="bg-orange-50/50 rounded-lg overflow-hidden border border-orange-200 shadow-sm block md:table-row my-2">
                                                            <td colSpan={5} className="p-4 block md:table-cell">
