  const startAdd = (item: PortfolioItem) => {
      const today = new Date().toISOString().split('T')[0].replace(/-/g, '/');
      const defaultPrice = item.etf.priceCurrent || 0;
      setAddingToId(item.id);
      setAddForm({
          id: Date.now().toString(),
          date: today,
          shares: 1000,
          price: defaultPrice,
          totalAmount: 1000 * defaultPrice
      });
