export default PortfolioView;

import React, { useState, useMemo } from 'react';
import { PortfolioItem, Transaction, EtfData } from '../types';
import { Trash2, ChevronDown, ChevronUp, Edit3, Save, Plus, BarChart3, TrendingUp, Wallet, ArrowUpRight, ArrowDownRight, Target } from 'lucide-react';

interface Props {
  portfolio: PortfolioItem[];
  onUpdateTransaction: (etfCode: string, tx: Transaction) => void;
  onDeleteTransaction: (etfCode: string, txId: string) => void;
  onAddTransaction: (etfCode: string, tx: Transaction) => void;
}

// 輔助函式：判斷債券類型 (回傳對應的股票分類 AA/AB/AC/AD)
const getBondType = (code: string): string => {
    // 月配 (AD)
    const monthlyBonds = ['00937B', '00772B', '00933B', '00773B'];
    if (monthlyBonds.some(b => code.includes(b))) return 'AD';

    // 季一 (AA): 1, 4, 7, 10
    const groupQ1 = ['00720B', '00725B', '00724B'];
    if (groupQ1.some(b => code.includes(b))) return 'AA';

    // 季二 (AB): 2, 5, 8, 11
    const groupQ2 = ['00679B', '00761B', '00795B'];
    if (groupQ2.some(b => code.includes(b))) return 'AB';

    // 季三 (AC): 3, 6, 9, 12
    const groupQ3 = ['00687B', '00751B', '00792B'];
    if (groupQ3.some(b => code.includes(b))) return 'AC';

    return 'AC'; // 預設季三
};

// 取得卡片顏色樣式
const getCardStyle = (etf: EtfData) => {
    let type = etf.category;
    if (etf.category === 'AE') {
        type = getBondType(etf.code) as any;
    }

    switch (type) {
        case 'AA': return 'bg-blue-50 border-blue-200';
        case 'AB': return 'bg-emerald-50 border-emerald-200';
        case 'AC': return 'bg-orange-50 border-orange-200';
        case 'AD': return 'bg-amber-50 border-amber-200';
        default: return 'bg-white border-slate-200';
    }
};

const PortfolioView: React.FC<Props> = ({ portfolio, onUpdateTransaction, onDeleteTransaction, onAddTransaction }) => {
  // UI State
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [editingTxId, setEditingTxId] = useState<string | null>(null);
  const [addingToId, setAddingToId] = useState<string | null>(null);

  // Forms
  const [editForm, setEditForm] = useState<Transaction | null>(null);
  const [addForm, setAddForm] = useState<Transaction | null>(null);

  // Toggle Expansion
  const toggleExpand = (id: string) => {
    if (expandedId === id) {
      setExpandedId(null);
    } else {
      setExpandedId(id);
    }
    setEditingTxId(null);
    setEditForm(null);
    setAddingToId(null);
    setAddForm(null);
  };

  // --- Add/Edit/Delete Handlers (保持原有邏輯) ---
  const startAdd = (item: PortfolioItem) => {
      const today = new Date().toISOString().split('T')[0].replace(/-/g, '/');
      const defaultPrice = item.etf.priceCurrent || 0;
      setAddingToId(item.id);
      setAddForm({
          id: Date.now().toString(),
          date: today,
          shares: 1000,
          price: defaultPrice,
          totalAmount: 1000 * defaultPrice
      });
      setExpandedId(item.id);
      setEditingTxId(null);
  };

  const handleAddChange = (field: keyof Transaction, value: string | number) => {
      if (!addForm) return;
      let newVal = value;
      if (field === 'price' || field === 'shares' || field === 'totalAmount') {
           newVal = Number(value);
      }
      const updated = { ...addForm, [field]: newVal };
      if (field === 'shares' || field === 'price') {
          updated.totalAmount = Number(updated.shares) * Number(updated.price);
      }
      setAddForm(updated);
  };

  const saveAdd = (etfCode: string) => {
      if (addForm) {
          onAddTransaction(etfCode, addForm);
          setAddingToId(null);
          setAddForm(null);
      }
  };

  const cancelAdd = () => {
      setAddingToId(null);
      setAddForm(null);
  };

  const startEdit = (tx: Transaction) => {
    setEditingTxId(tx.id);
    setEditForm({ ...tx });
    setAddingToId(null);
  };

  const handleEditChange = (field: keyof Transaction, value: string | number) => {
    if (!editForm) return;
    let newVal = value;
    if (field === 'price' || field === 'shares' || field === 'totalAmount') {
         newVal = Number(value);
    }
    const updated = { ...editForm, [field]: newVal };
    if (field === 'shares' || field === 'price') {
        updated.totalAmount = Number(updated.shares) * Number(updated.price);
    }
    setEditForm(updated);
  };

  const saveEdit = (etfCode: string) => {
      if (editForm) {
          onUpdateTransaction(etfCode, editForm);
          setEditingTxId(null);
          setEditForm(null);
      }
  };

  const cancelEdit = () => {
      setEditingTxId(null);
      setEditForm(null);
  };

  const handleDeleteClick = (etfCode: string, txId: string) => {
      if (window.confirm("確定要刪除此筆交易紀錄嗎？")) {
          onDeleteTransaction(etfCode, txId);
      }
  };

  // --- Aggregates for A1 (Statistics) ---
  const grandTotalCost = portfolio.reduce((sum, item) => {
      return sum + item.transactions.reduce((tSum, tx) => tSum + tx.totalAmount, 0);
  }, 0);

  const totalMonthlyIncome = portfolio.reduce((sum, item) => {
      const totalShares = item.transactions.reduce((s, tx) => s + tx.shares, 0);
      return sum + (item.etf.priceCurrent * totalShares * item.etf.dividendYield / 100 / 12); 
  }, 0);

  const estimatedAnnualIncome = totalMonthlyIncome * 12;
  const holdingsCount = portfolio.length;

  // --- Aggregates for Asset Analysis (P/L) ---
  const currentMarketValue = portfolio.reduce((sum, item) => {
      const totalShares = item.transactions.reduce((s, tx) => s + tx.shares, 0);
      return sum + (totalShares * item.etf.priceCurrent);
  }, 0);

  const unrealizedPL = currentMarketValue - grandTotalCost;
  const plRate = grandTotalCost > 0 ? (unrealizedPL / grandTotalCost) * 100 : 0;

  // --- A3 Analysis Data Calculation ---
  const analysisData = useMemo(() => {
    const months = Array(12).fill(0); // Index 0 = Jan

    portfolio.forEach(item => {
        const totalShares = item.transactions.reduce((s, tx) => s + tx.shares, 0);
        // Annual projected dividend for this item based on Current Price and Yield
        // If dividendYield is missing (NaN/0), this will be 0.
        const annualDiv = item.etf.priceCurrent * totalShares * (item.etf.dividendYield / 100);

        let type = item.etf.category;
        if (type === 'AE') {
            type = getBondType(item.etf.code) as any;
        }

        if (annualDiv > 0) {
            if (type === 'AD') {
                // 月配: 均分 12 個月
                const monthly = annualDiv / 12;
                for(let i=0; i<12; i++) months[i] += monthly;
            } else if (type === 'AA') {
                // 季一: 1, 4, 7, 10 (Index: 0, 3, 6, 9)
                const quarterly = annualDiv / 4;
                [0, 3, 6, 9].forEach(m => months[m] += quarterly);
            } else if (type === 'AB') {
                // 季二: 2, 5, 8, 11 (Index: 1, 4, 7, 10)
                const quarterly = annualDiv / 4;
                [1, 4, 7, 10].forEach(m => months[m] += quarterly);
            } else if (type === 'AC') {
                 // 季三: 3, 6, 9, 12 (Index: 2, 5, 8, 11)
                 const quarterly = annualDiv / 4;
                 [2, 5, 8, 11].forEach(m => months[m] += quarterly);
            }
        }
    });

    // 累積成長曲線 (Cumulative Growth of Asset Value)
    // 起點：目前總市值 (currentMarketValue)
    // 每月：加上該月的股息
    let accumulatedValue = currentMarketValue;
    const accumulation = months.map(m => {
        accumulatedValue += m;
        return accumulatedValue;
    });

    const totalDividend = accumulatedValue - currentMarketValue;

    // Determine Chart Scale (Y-Axis)
    // Must include: Grand Total Cost (Baseline) AND Max Asset Value (Peak)
    // Add 5% padding
    const dataPoints = [grandTotalCost, currentMarketValue, ...accumulation].filter(v => v > 0);
    const maxY = Math.max(...dataPoints) * 1.02;
    const minY = Math.min(...dataPoints) * 0.98;

    return { 
        monthly: months, 
        cumulative: accumulation, 
        maxMonth: Math.max(...months), 
        maxY,
        minY,
        totalDividend,
        finalProjectedValue: accumulatedValue
    };
  }, [portfolio, currentMarketValue, grandTotalCost]);

  const hasAnalysisData = analysisData.maxMonth > 0;

  // New Metrics for Chart Description
