                        <div className="flex flex-col gap-1 border-l border-slate-200">
                            <span className="text-[10px] text-slate-400">平均報酬率</span>
                            <span className={`font-bold text-sm ${avgReturnRate >= 0 ? 'text-red-600' : 'text-green-600'}`}>
                                {avgReturnRate.toFixed(2)}%
                            </span>
                        </div>
                    </div>
                </div>
            </div>
          )}
      </div>
    </div>
  );
};

