import { GoogleGenAI } from "@google/genai";
import { PortfolioItem, EtfData } from "../types";

// 安全獲取 API Key 的輔助函式
const getSafeApiKey = (): string => {
  try {
    if (typeof process !== 'undefined' && process && process.env) {
      return process.env.API_KEY || '';
    }
  } catch (e) {
    console.warn("Environment variable access failed gracefully.");
  }
  return '';
};

// 更新函式簽章以接收 PortfolioItem[]
export const analyzeSheets = async (
  portfolio: PortfolioItem[],
  onStream: (text: string) => void
): Promise<void> => {
  const modelId = 'gemini-3-flash-preview'; 
  const apiKey = getSafeApiKey();
  const ai = new GoogleGenAI({ apiKey });

  // 將 Portfolio 物件轉換為簡化的 JSON 字串供 AI 閱讀
  const portfolioSummary = portfolio.map(item => ({
      code: item.id,
      name: item.etf.name,
      category: item.etf.category,
      totalCost: item.transactions.reduce((s, t) => s + t.totalAmount, 0),
      currentPrice: item.etf.priceCurrent,
      dividendYield: item.etf.dividendYield
  }));

  const prompt = `
    你現在是一位專業的 ETF 投資組合顧問。
    以下是使用者目前的「自組月配」投資組合清單：
    ${JSON.stringify(portfolioSummary, null, 2)}

    請針對這份清單進行以下三個維度的深入診斷，並以 Markdown 表格呈現結果：

    1. **產業分散性 (Industry Diversification)**: 分析這些 ETF 的成分股是否過度集中於特定產業 (如半導體、金融等)，或是否足夠分散。
    2. **每月收益均衡化 (Monthly Income Balance)**: 根據這些 ETF 的配息特性 (月配/季配)，分析使用者是否能達成「月月配」的現金流目標，是否有月份空窗或收益波動過大。
    3. **防禦性分析 (Defensive Analysis)**: 在市場下跌時，這組配置的抗跌能力如何？(例如是否有債券、低波高息股等防禦型資產)。

    **輸出格式要求**：
    請直接輸出一個清晰的 Markdown 表格，包含以下欄位：
    | 診斷維度 | 分析結果 | 優化建議 |
    |---|---|---|
    | 產業分散 | ... | ... |
    | 收益均衡 | ... | ... |
    | 防禦能力 | ... | ... |

    最後請給出一段 100 字以內的總結建議。
  `;

  try {
    const response = await ai.models.generateContentStream({
      model: modelId,
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        thinkingConfig: { thinkingBudget: 0 }
      }
    });

    for await (const chunk of response) {
      if (chunk.text) {
        onStream(chunk.text);
      }
    }
  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    throw error;
  }
};

// 新增：智慧規劃功能
export const generateSmartPlan = async (
  etfs: EtfData[],
  budgetWan: number,
  userRequest: string,
  onStream: (text: string) => void
): Promise<void> => {
  const modelId = 'gemini-3-flash-preview';
  const apiKey = getSafeApiKey();
  const ai = new GoogleGenAI({ apiKey });

  const totalBudget = budgetWan * 10000;

  // 簡化 ETF 資料，減少 Token 使用並聚焦重點
  const etfSummary = etfs.map(e => ({
    code: e.code,
    name: e.name,
    category: e.category,
    price: e.priceCurrent,
    yield: e.dividendYield,
    estYield: e.estYield,
    type: e.category === 'AE' ? '債券' : (e.category === 'AD' ? '股票(月配)' : '股票(季配)')
  }));

  const prompt = `
    你是一位專業的投資理財顧問。
    使用者想要進行 ETF 投資規劃。

    **投資參數：**
    1. 總預算：${totalBudget.toLocaleString()} 台幣 (TWD)
    2. 使用者需求描述：${userRequest}

    **可用 ETF 清單 (只能從這裡選擇)：**
    ${JSON.stringify(etfSummary)}

    **任務：**
    請根據使用者的預算與需求，從「可用 ETF 清單」中挑選適合的標的，建立一個投資組合。

    **計算規則：**
    1. 請精確計算每檔 ETF 的購買「股數」與「預估成本」。
    2. 股數建議以 1000 股 (一張) 為單位，若預算不足可配零股，但盡量以整張為主。
    3. 總成本不能超過總預算。
    4. 必須嚴格遵守使用者對於「股債比」、「配息頻率(季配/月配)」的要求。

    **輸出格式 (必須是 Markdown 表格)：**

    請直接輸出表格，不要有過多的開場白。表格欄位如下：
    | 代號 | 名稱 | 類型 | 建議股數 | 預估成本 | 預估殖利率 | 推薦理由 |
    |---|---|---|---|---|---|---|
    | ... | ... | ... | ... | ... | ... | ... |

    **表格後方補充：**
    1. **預估總成本**：$xxx
    2. **預估年領股息**：$xxx
    3. **配置分析**：簡短說明此配置如何滿足使用者的需求 (例如股債比是否達標)。
  `;

  try {
    const response = await ai.models.generateContentStream({
      model: modelId,
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      config: {
        thinkingConfig: { thinkingBudget: 0 }
      }
    });

    for await (const chunk of response) {
      if (chunk.text) {
        onStream(chunk.text);
      }
    }
  } catch (error) {
    console.error("Gemini Planning Error:", error);
    throw error;
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { EtfData } from '../types';
import { generateSmartPlan } from '../services/geminiService';
import { BrainCircuit, Mic, MicOff, Play, RefreshCcw, Coins } from 'lucide-react';
import ReactMarkdown from 'react-markdown';

interface Props {
  etfs: EtfData[];
}

const DEFAULT_PROMPT = "股債配置 80 : 20 , 股票產業分散 ,季配型各季 * 1 , 月配 * 2 , 均衡股息收入";

const PlanningView: React.FC<Props> = ({ etfs }) => {
  // Input State
  const [budget, setBudget] = useState<number>(500); // Unit: 萬
  const [prompt, setPrompt] = useState<string>(DEFAULT_PROMPT);

  // Interaction State
  const [isListening, setIsListening] = useState(false);
  const [isGenerating, setIsGenerating] = useState(false);
  const [result, setResult] = useState<string>("");

  // Refs
  const recognitionRef = useRef<any>(null);

  useEffect(() => {
    // Initialize Speech Recognition if available
    if (typeof window !== 'undefined') {
      const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
      if (SpeechRecognition) {
        recognitionRef.current = new SpeechRecognition();
        recognitionRef.current.continuous = false;
        recognitionRef.current.lang = 'zh-TW';
        recognitionRef.current.interimResults = false;

        recognitionRef.current.onresult = (event: any) => {
          const transcript = event.results[0][0].transcript;
          setPrompt(prev => prev ? `${prev} , ${transcript}` : transcript);
          setIsListening(false);
        };

        recognitionRef.current.onerror = (event: any) => {
          console.error("Speech recognition error", event.error);
          setIsListening(false);
        };

        recognitionRef.current.onend = () => {
          setIsListening(false);
        };
      }
    }
  }, []);

  const toggleListening = () => {
    if (!recognitionRef.current) {
      alert("您的瀏覽器不支援語音輸入功能");
      return;
    }

    if (isListening) {
      recognitionRef.current.stop();
      setIsListening(false);
    } else {
      recognitionRef.current.start();
      setIsListening(true);
    }
  };

  const handleStartPlanning = async () => {
    if (!prompt.trim()) {
      alert("請輸入規劃需求");
      return;
    }
    if (etfs.length === 0) {
      alert("目前無 ETF 資料，無法進行規劃，請先至「設定資料來源」讀取資料。");
      return;
    }

    setIsGenerating(true);
    setResult(""); // Clear previous result

    try {
      await generateSmartPlan(etfs, budget, prompt, (text) => {
        setResult(prev => prev + text);
      });
    } catch (e) {
      setResult("規劃過程發生錯誤，請稍後再試。");
    } finally {
      setIsGenerating(false);
    }
  };

  return (
    <div className="flex flex-col h-full bg-slate-50 p-4 overflow-y-auto scrollbar-hide">

      {/* Input Card */}
      <div className="bg-white rounded-2xl shadow-sm border border-slate-200 p-5 mb-6 shrink-0">
        <div className="flex items-center gap-2 mb-4 border-b border-slate-100 pb-2">
          <BrainCircuit className="w-6 h-6 text-purple-600" />
          <h2 className="text-xl font-bold text-slate-800">AI 智慧規劃</h2>
        </div>

        <div className="space-y-5">
          {/* Budget Input */}
          <div>
            <label className="block text-sm font-bold text-slate-600 mb-2 flex items-center gap-1">
              <Coins className="w-4 h-4 text-amber-500" />
              規劃金額 (萬元)
            </label>
            <div className="relative">
              <input
                type="number"
                value={budget}
                onChange={(e) => setBudget(Number(e.target.value))}
                className="w-full pl-4 pr-12 py-3 bg-slate-50 border border-slate-300 rounded-xl text-lg font-bold text-slate-800 focus:ring-2 focus:ring-purple-200 focus:border-purple-500 transition-all text-right"
              />
              <span className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 font-bold">萬</span>
            </div>
            <p className="text-xs text-slate-400 mt-1 text-right">
              約 {(budget * 10000).toLocaleString()} TWD
            </p>
          </div>

          {/* Prompt Input */}
          <div>
            <label className="block text-sm font-bold text-slate-600 mb-2 flex justify-between items-center">
              <span>規劃提示詞 (Prompt)</span>
              <span className="text-xs font-normal text-purple-600 bg-purple-50 px-2 py-0.5 rounded-full">
                可語音輸入
              </span>
            </label>
            <div className="relative">
              <textarea
                value={prompt}
                onChange={(e) => setPrompt(e.target.value)}
                className="w-full p-4 pr-12 bg-slate-50 border border-slate-300 rounded-xl text-base text-slate-700 focus:ring-2 focus:ring-purple-200 focus:border-purple-500 transition-all min-h-[120px] resize-none leading-relaxed"
                placeholder="請輸入您的投資策略..."
              />
              <button
                onClick={toggleListening}
                className={`absolute right-3 bottom-3 p-2 rounded-full transition-all shadow-sm ${
                  isListening 
                    ? 'bg-red-500 text-white animate-pulse' 
                    : 'bg-white text-slate-400 border border-slate-200 hover:text-purple-600 hover:border-purple-200'
                }`}
                title="語音輸入"
              >
                {isListening ? <MicOff className="w-5 h-5" /> : <Mic className="w-5 h-5" />}
              </button>
            </div>
          </div>

          {/* Action Button */}
          <button
            onClick={handleStartPlanning}
            disabled={isGenerating}
            className={`w-full py-3.5 rounded-xl font-bold text-white shadow-md flex items-center justify-center gap-2 text-lg transition-all active:scale-[0.98] ${
              isGenerating 
                ? 'bg-purple-400 cursor-not-allowed' 
                : 'bg-purple-700 hover:bg-purple-800'
            }`}
          >
            {isGenerating ? (
              <>
                <RefreshCcw className="w-5 h-5 animate-spin" />
                規劃運算中...
              </>
            ) : (
              <>
                <Play className="w-5 h-5 fill-current" />
                開始規劃
              </>
            )}
          </button>
        </div>
      </div>

      {/* Result Area */}
      {result && (
        <div className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6 animate-[fadeIn_0.5s_ease-out] mb-6">
          <div className="prose prose-slate max-w-none prose-table:border-collapse prose-table:w-full prose-th:bg-purple-50 prose-th:text-purple-900 prose-th:p-3 prose-td:p-3 prose-td:border-b prose-td:border-slate-100">
             <ReactMarkdown 
                components={{
                    table: ({node, ...props}) => <div className="overflow-x-auto"><table className="w-full text-sm text-left whitespace-nowrap" {...props} /></div>,
                    thead: ({node, ...props}) => <thead className="bg-purple-50 text-purple-900 font-bold" {...props} />,
                    th: ({node, ...props}) => <th className="px-3 py-3 border-b border-purple-100" {...props} />,
                    td: ({node, ...props}) => <td className="px-3 py-3 border-b border-slate-100 text-slate-700" {...props} />
                }}
             >
                {result}
             </ReactMarkdown>
          </div>
        </div>
      )}
    </div>
  );
};

