          <BrainCircuit className="w-6 h-6 text-purple-600" />
          <h2 className="text-xl font-bold text-slate-800">AI 智慧規劃</h2>
        </div>

        <div className="space-y-5">
          {/* Budget Input */}
          <div>
            <label className="block text-sm font-bold text-slate-600 mb-2 flex items-center gap-1">
              <Coins className="w-4 h-4 text-amber-500" />
              規劃金額 (萬元)
            </label>
            <div className="relative">
              <input
                type="number"
                value={budget}
                onChange={(e) => setBudget(Number(e.target.value))}
                className="w-full pl-4 pr-12 py-3 bg-slate-50 border border-slate-300 rounded-xl text-lg font-bold text-slate-800 focus:ring-2 focus:ring-purple-200 focus:border-purple-500 transition-all text-right"
              />
              <span className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 font-bold">萬</span>
            </div>
            <p className="text-xs text-slate-400 mt-1 text-right">
              約 {(budget * 10000).toLocaleString()} TWD
            </p>
          </div>

          {/* Prompt Input */}
          <div>
            <label className="block text-sm font-bold text-slate-600 mb-2 flex justify-between items-center">
              <span>規劃提示詞 (Prompt)</span>
              <span className="text-xs font-normal text-purple-600 bg-purple-50 px-2 py-0.5 rounded-full">
                可語音輸入
              </span>
            </label>
            <div className="relative">
              <textarea
                value={prompt}
                onChange={(e) => setPrompt(e.target.value)}
                className="w-full p-4 pr-12 bg-slate-50 border border-slate-300 rounded-xl text-base text-slate-700 focus:ring-2 focus:ring-purple-200 focus:border-purple-500 transition-all min-h-[120px] resize-none leading-relaxed"
                placeholder="請輸入您的投資策略..."
              />
              <button
                onClick={toggleListening}
                className={`absolute right-3 bottom-3 p-2 rounded-full transition-all shadow-sm ${
                  isListening 
                    ? 'bg-red-500 text-white animate-pulse' 
                    : 'bg-white text-slate-400 border border-slate-200 hover:text-purple-600 hover:border-purple-200'
                }`}
                title="語音輸入"
              >
                {isListening ? <MicOff className="w-5 h-5" /> : <Mic className="w-5 h-5" />}
              </button>
            </div>
          </div>

          {/* Action Button */}
          <button
            onClick={handleStartPlanning}
            disabled={isGenerating}
            className={`w-full py-3.5 rounded-xl font-bold text-white shadow-md flex items-center justify-center gap-2 text-lg transition-all active:scale-[0.98] ${
              isGenerating 
                ? 'bg-purple-400 cursor-not-allowed' 
                : 'bg-purple-700 hover:bg-purple-800'
            }`}
          >
            {isGenerating ? (
              <>
                <RefreshCcw className="w-5 h-5 animate-spin" />
