          ];

    // SVG 繪圖計算
    const prices = dataPoints.map(d => d.price);
    const maxY = Math.max(...prices) * 1.02; // 上下留白
    const minY = Math.min(...prices) * 0.98;
    const rangeY = maxY - minY || 1;
    const count = dataPoints.length;

    const getX = (index: number) => {
        if (count <= 1) return 50;
        return (index / (count - 1)) * 100;
    }
    const getY = (val: number) => 100 - ((val - minY) / rangeY) * 100;

    const points = dataPoints.map((d, i) => `${getX(i)},${getY(d.price)}`).join(' ');

    // 準備表格數據 (倒序: 最近的在上面 Newest -> Oldest)
    // 欄位：日期 | 股價 | 報酬率 (與前一個月相比)
    const tableData = [...dataPoints].reverse().map((curr, idx, arr) => {
        // arr is reversed, so next item in arr (idx + 1) is the previous month chronologically
        const prev = arr[idx + 1];
        let rate = 0;

        if (prev && prev.price > 0) {
            rate = ((curr.price - prev.price) / prev.price) * 100;
        }

        return {
            date: curr.date,
            price: curr.price,
            rate: rate
        };
    });

    return (
        <div className="fixed inset-0 z-50 flex flex-col bg-white animate-[fadeIn_0.2s_ease-out]">
            {/* Header */}
            <div className="h-12 bg-white flex items-center justify-between px-4 border-b border-slate-100">
