                 <button onClick={() => setChartEtf(null)} className="p-2 bg-slate-100 rounded-full text-slate-500">
                    <X className="w-5 h-5" />
                 </button>
            </div>

            {/* Area 1: Chart (50%) */}
            <div className="flex-1 p-4 flex flex-col justify-center border-b border-slate-100 relative min-h-[40vh]">
                <div className="absolute top-2 right-4 flex flex-col items-end text-[10px] text-slate-500 gap-1">
                    <div className="flex items-center gap-1"><div className="w-3 h-0.5 bg-blue-500"></div>歷史股價</div>
                </div>
                <div className="w-full h-4/5 relative">
                     <svg className="w-full h-full overflow-visible" viewBox="0 0 100 100" preserveAspectRatio="none">
                        {/* Grid Lines */}
                        <line x1="0" y1="0" x2="100" y2="0" stroke="#f1f5f9" strokeWidth="1" />
                        <line x1="0" y1="50" x2="100" y2="50" stroke="#f1f5f9" strokeWidth="1" />
                        <line x1="0" y1="100" x2="100" y2="100" stroke="#f1f5f9" strokeWidth="1" />

                        {/* Price Line (Blue) */}
                        <polyline 
                            fill="none" 
                            stroke="#3b82f6" 
                            strokeWidth="3" 
                            strokeLinecap="round"
                            strokeLinejoin="round"
                            points={points} 
                        />
                        {/* Dots */}
                        {dataPoints.map((d, i) => (
                            <circle key={i} cx={getX(i)} cy={getY(d.price)} r="2" fill="#3b82f6" />
                        ))}
                     </svg>
                     <div className="flex justify-between mt-2 text-[12px] text-slate-400">
                         <span>{dataPoints[0]?.date}</span>
                         <span>{dataPoints[dataPoints.length-1]?.date}</span>
                     </div>
                </div>
            </div>

            {/* Area 2: Table (50%) */}
            <div className="flex-1 bg-slate-50 p-4 overflow-y-auto">
                <table className="w-full text-left">
                    <thead>
                        {/* 標題文字 12 px 細字 */}
                        <tr className="text-[12px] font-light text-slate-500 border-b border-slate-200">
                            <th className="py-2 text-left font-light">日期</th>
                            <th className="py-2 text-right font-light">股價</th>
                            <th className="py-2 text-right font-light">報酬率</th>
                        </tr>
                    </thead>
                    <tbody>
                        {tableData.map((row, idx) => (
                            <tr key={idx} className="border-b border-slate-200/50">
                                {/* 內容文字 : 18 px 粗字 */}
                                <td className="py-3 text-[18px] text-slate-800 font-bold">{row.date}</td>
                                <td className="py-3 text-[18px] text-slate-800 font-bold text-right">{row.price}</td>
                                <td className={`py-3 text-[18px] font-bold text-right ${row.rate > 0 ? 'text-red-600' : row.rate < 0 ? 'text-green-600' : 'text-slate-800'}`}>
                                    {row.rate !== 0 ? `${row.rate.toFixed(2)}%` : '-'}
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        </div>
    );
  };

  // --- 彈跳視窗：g. 詳細資料 ---
  const renderDetailModal = () => {
      if (!selectedEtf) return null;

      const cardColorClass = getCardStyle(selectedEtf).split(' ')[0]; // 只取 bg color

      // 判斷月配/季配
      // 若是債券，需判斷是否為月配債
      let isMonthly = selectedEtf.category === 'AD';
      if (selectedEtf.category === 'AE') {
          const monthlyBonds = ['00937B', '00772B', '00933B', '00773B'];
          if (monthlyBonds.some(b => selectedEtf.code.includes(b))) isMonthly = true;
      }

      const count = isMonthly ? 12 : 4;

      // 排序配息：近 -> 遠
      const allDivs = [...selectedEtf.dividends].sort((a, b) => getDateValue(b.date) - getDateValue(a.date));

      // 檢查是否有未來配息
