                 );
             })
         ) : (
            <div className="py-12 text-center text-slate-400 text-sm">
                目前分類無資料
            </div>
         )}
      </div>

      {/* Modals */}
      {renderDetailModal()}
      {renderChartModal()}

    </div>
  );
};

