                                            </td>
                                        </tr>
                                    );
                                })
                             ) : (
                                <tr><td colSpan={4} className="py-8 text-center text-slate-400">無配息資料</td></tr>
                             )}
                        </tbody>
                    </table>
                 </div>
            </div>
        </div>
      );
  };

  return (
    <div className="flex flex-col h-full bg-slate-50">

      {/* A1 + A2 Fixed Header */}
