      const allDivs = [...selectedEtf.dividends].sort((a, b) => getDateValue(b.date) - getDateValue(a.date));

      // 檢查是否有未來配息
      const hasFuture = allDivs.length > 0 && isFutureDate(allDivs[0].date);
