                                <span className={`text-[16px] font-medium leading-none ${etf.totalReturn >= 0 ? 'text-red-600' : 'text-green-600'}`}>
                                    {etf.totalReturn}%
                                </span>
                            </div>
                            <div className="text-right flex justify-end px-1">
                                {/* 按鈕: 詳細資料 (CircleAlert) */}
                                <button 
