                                                    <button onClick={() => startEdit(tx)} className="ml-2 px-2 py-0.5 bg-red-50 text-red-600 rounded text-[12px] border border-red-100">修改</button>
                                                </div>
                                            </div>
                                        );
                                    })}
                                </div>
                            )}
                        </div>
                    );
                })}
            </div>
          )}

          {hasData && (
            <div className="pt-2 pb-6 space-y-3">

                {/* A3-A. 資產價值損益 */}
