                                                            <input type="text" value={editForm!.totalAmount} onChange={(e) => handleFormChange('edit', 'totalAmount', e.target.value)} className="w-full text-[16px] border rounded px-1 text-right bg-white text-slate-700 font-normal" />
                                                        </div>
                                                    </div>
                                                    {/* Row 2: 股數, 單價 */}
