                      <p>※ 單次殖利率計算方式：配息金額 / 目前股價 ({selectedEtf.priceCurrent})。</p>
                  </div>
              </div>
          </div>
      );
  }

  // --- 列表清單頁面 (A1, A2 固定，A3 滑動) ---
