                                    {row.rate !== 0 ? `${row.rate.toFixed(2)}%` : '-'}
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        </div>
    );
  };

  // --- 彈跳視窗：g. 詳細資料 ---
  const renderDetailModal = () => {
