      const targetCodes = CATEGORY_MAPPING[activeFilter] || [];
      return etfs.filter(e => 
          ['AA', 'AB', 'AC'].includes(e.category) && targetCodes.some(code => e.code.includes(code))
      ).sort((a,b) => a.code.localeCompare(b.code));
  }, [etfs, activeFilter]);

