    const getY = (val: number) => 100 - ((val - minY) / rangeY) * 100;

    const pointsPrice = chartData.map((d, i) => `${getX(i)},${getY(d.price)}`).join(' ');
    const pointsTotal = chartData.map((d, i) => `${getX(i)},${getY(d.totalPrice)}`).join(' ');

