  '國際': ['00645', '00646', '00662', '00757', '00762', '00830', '00885', '00893', '00895', '00909', '00910', '00911'],
  // '月配' 與 '債券' 直接透過 CategoryKey 判斷
};

// 用於顯示灰色底色的列表 (國際、無配息、年配、半年配、特定主動型)
const GRAY_CODES = [
    // 國際/海外
    '00645', '00646', '00662', '00757', '00762', '00830', '00885', '00893', '00895', '00909', '00910', '00911',
    // 指定主動型/無配息/年配
    '00981A', '00983A', '00986A'
];

// 輔助：判斷是否為未來日期
const isFutureDate = (dateStr: string) => {
    if (!dateStr) return false;
    const cleanStr = dateStr.trim();
    let dateVal = 0;
    if (/^\d{6}$/.test(cleanStr)) {
        const y = parseInt(cleanStr.substring(0, 4));
        const m = parseInt(cleanStr.substring(4, 6)) - 1;
        dateVal = new Date(y, m, 1).getTime();
    } else {
        const standardDate = new Date(cleanStr.replace(/\./g, '/').replace(/-/g, '/'));
        if (!isNaN(standardDate.getTime())) dateVal = standardDate.getTime();
    }

    const today = new Date();
    today.setHours(0, 0, 0, 0);
    return dateVal > today.getTime();
};

const getDateValue = (dateStr: string): number => {
    if (!dateStr) return 0;
    const cleanStr = dateStr.trim();
    if (/^\d{6}$/.test(cleanStr)) {
        const y = parseInt(cleanStr.substring(0, 4));
        const m = parseInt(cleanStr.substring(4, 6)) - 1;
        return new Date(y, m, 1).getTime();
    }
    const standardDate = new Date(cleanStr.replace(/\./g, '/').replace(/-/g, '/'));
    if (!isNaN(standardDate.getTime())) {
        return standardDate.getTime();
    }
    return 0;
};

// 輔助：格式化日期 yyyy/MM/dd (強制補零)
const formatDate = (dateStr: string): string => {
    if (!dateStr) return '';
    const cleanStr = dateStr.trim();
    let y = '', m = '', d = '';

    // 處理純數字 YYYYMMDD
    if (/^\d{8}$/.test(cleanStr)) {
         y = cleanStr.substring(0, 4);
         m = cleanStr.substring(4, 6);
         d = cleanStr.substring(6, 8);
         return `${y}/${m}/${d}`;
    }

    // 處理 YYYYMM
    if (/^\d{6}$/.test(cleanStr)) {
        y = cleanStr.substring(0, 4);
        m = cleanStr.substring(4, 6);
        d = '01'; // Default day for monthly data
        return `${y}/${m}/${d}`;
    } 

    // 處理分隔符
    const parts = cleanStr.split(/[\/\.\-]/);
    if (parts.length >= 2) {
        y = parts[0];
        m = parts[1].padStart(2, '0');
        d = parts[2] ? parts[2].padStart(2, '0') : '01';
        return `${y}/${m}/${d}`;
    }

    return cleanStr;
};

// 輔助：取得卡片顏色樣式 (更新邏輯)
const getCardStyle = (etf: EtfData) => {
    // 1. 特殊名單：國際/無配息/年配/半年配/指定主動 -> 淡灰色
    if (GRAY_CODES.includes(etf.code)) {
        return 'bg-slate-100 border-slate-300';
    }

    let type = etf.category;

    // 2. 債券：根據配息頻率重新歸類
    if (etf.category === 'AE') {
        const code = etf.code;
        const monthlyBonds = ['00937B', '00772B', '00933B', '00773B'];

        if (monthlyBonds.some(b => code.includes(b))) type = 'AD'; // 月配 -> 茶色
        else if (['00720B', '00725B', '00724B'].some(b => code.includes(b))) type = 'AA'; // 季一 -> 藍色
        else if (['00679B', '00761B', '00795B'].some(b => code.includes(b))) type = 'AB'; // 季二 -> 綠色
        else type = 'AC'; // 季三/其他 -> 橘色
    }

    switch (type) {
        case 'AA': return 'bg-blue-50 border-blue-200';     // 季一: 淡藍
        case 'AB': return 'bg-emerald-50 border-emerald-200'; // 季二: 淡綠
        case 'AC': return 'bg-orange-50 border-orange-200';  // 季三: 淡橘
        case 'AD': return 'bg-amber-50 border-amber-200';    // 月配: 淡茶色
        default: return 'bg-slate-100 border-slate-300';      // 預設: 淡灰色
    }
};

const AnalysisView: React.FC<Props> = ({ etfs, lastUpdated, onAddToPortfolio }) => {
  const [activeFilter, setActiveFilter] = useState('高息');
