                 <button onClick={() => setChartEtf(null)} className="p-2 bg-slate-100 rounded-full text-slate-500">
                    <X className="w-5 h-5" />
                 </button>
            </div>

            {/* Area 1: Chart (比例 2:1 = 4:2) */}
