/**
 * Parses the Dividend CSV content.
 */
export const parseDividendData = (csvContent: string): Record<string, Dividend[]> => {
  const lines = csvContent.split(/\r?\n/).filter(line => line.trim() !== '');
  if (lines.length < 2) return {};

  const dividendMap: Record<string, Dividend[]> = {};

  // 1. Header Detection
  let headerRowIndex = 0;
  // Use parseCSVRow for header as well
  let header = parseCSVRow(lines[0]).map(c => c.trim().toLowerCase());

  // Scan for header if first row isn't it
  if (!header.some(h => h.includes('代號') || h.includes('code') || h.includes('etf 代碼') || h.includes('symbol'))) {
      for(let i=0; i<Math.min(lines.length, 5); i++) {
          const rowValues = parseCSVRow(lines[i]);
          const rowLower = rowValues.map(c => c.toLowerCase());

          if (rowLower.some(c => c.includes('代號') || c.includes('code') || c.includes('etf 代碼') || c.includes('symbol'))) {
              headerRowIndex = i;
              header = rowLower;
              break;
          }
      }
  }

  const findCol = (keywords: string[]) => header.findIndex(h => keywords.some(k => h.includes(k)));

  const idxCode = findCol(['etf 代碼', '股號', '代號', 'code', '股票代號', 'symbol', '代碼']);
  // 移除 '發放日' 以避免混淆，專注於除息相關關鍵字
  const idxDate = findCol(['除息日期', '除息日', 'date', '配息日', '日期', '除息交易日', '除息']);
  const idxAmount = findCol(['除息金額', '配息', '金額', 'amount', '現金股利', '分配金額', '現金', '股利', 'distribution']);
  // 明確指定發放日關鍵字
  const idxPayDate = findCol(['發放日', '現金股利發放日', '入帳日', '領息日', 'payment', 'pay', '發放']);

  if (idxCode === -1 || idxAmount === -1) {
      console.warn("Parse Dividend Failed: Missing required columns (Code or Amount). Header:", header);
      return {};
  }

  for (let i = headerRowIndex + 1; i < lines.length; i++) {
      const row = parseCSVRow(lines[i]);
      if (row.length <= idxCode) continue;

      const rawCode = row[idxCode];
      const code = rawCode ? rawCode.replace(/['"]/g, '').trim() : '';

      if (code) {
          const amountStr = row[idxAmount]?.replace(/[^0-9.]/g, '') || '0';
          const amount = parseFloat(amountStr);
          let date = idxDate !== -1 ? row[idxDate] : '';

          if (date) date = date.replace(/['"]/g, '').trim();

          // 解析發放日
          let paymentDate = '';
          if (idxPayDate !== -1 && row[idxPayDate]) {
              paymentDate = row[idxPayDate].replace(/['"]/g, '').trim();
          }

          if (amount > 0) {
              if (!dividendMap[code]) {
                  dividendMap[code] = [];
              }
              dividendMap[code].push({
                  date: date,
                  amount: amount,
                  period: '',
                  paymentDate: paymentDate 
              });
          }
      }
  }
  return dividendMap;
};

/**
 * Parses the CSV content strictly with robust header detection.
 */
export const parseEtfData = (csvContent: string): EtfData[] => {
  const lines = csvContent.split(/\r?\n/).filter(line => line.trim() !== '');
  if (lines.length < 2) return [];

  const etfs: EtfData[] = [];

  // --- 1. Robust Header Row Detection ---
  let headerRowIndex = -1;
  let header: string[] = [];

  for (let i = 0; i < Math.min(lines.length, 10); i++) {
     const rowValues = parseCSVRow(lines[i]);
     const rowLower = rowValues.map(c => c.toLowerCase());

     if (rowLower.some(c => c.includes('代碼') || c.includes('代號') || c.includes('code') || c.includes('etf 代碼') || c.includes('symbol'))) {
         headerRowIndex = i;
         header = rowLower;
         break;
     }
  }

  if (headerRowIndex === -1) {
     headerRowIndex = 0;
     header = parseCSVRow(lines[0]).map(c => c.toLowerCase());
  }

  const findCol = (keywords: string[]) => header.findIndex(h => keywords.some(k => h.includes(k)));

  const idxCode = findCol(['etf 代碼', '股號', '代碼', '代號', 'code', 'symbol', '股票代號']);
  const idxName = findCol(['etf 名稱', '股名', '股票名稱', 'etf名稱', '名稱', 'name']); 
  const idxMarket = findCol(['上市/ 上櫃', '市場', 'market', '類別', '上市', '上櫃', 'type', '掛牌']); 

  // --- 2. Dynamic Price Column Detection ---
  // 修改：捕捉所有日期欄位作為歷史數據，並特別處理 "NOW()-1"
  const dateColIndices = header.map((h, index) => {
      // Matches YYYY/MM/DD, YYYY-MM-DD, MM/DD, YYYYMM (6 digits), YYYY/MM (for monthly data)
      const isDate = /(\d{1,4}[-./]\d{1,2}[-./]\d{1,2})|(\d{1,2}[-./]\d{1,2})|(\d{4}[-./]\d{1,2})/.test(h) || /^\d{6}$/.test(h.replace(/\//g,''));

      // 特別偵測 "NOW()-1" 標題
      const isYesterdayKey = h.includes('now()-1') || h.includes('now() - 1');

      if (isDate || isYesterdayKey) {
          let label = parseCSVRow(lines[headerRowIndex])[index].trim();

          // 如果是 "NOW()-1"，將標籤轉換為昨天的實際日期字串，方便後續排序邏輯
          if (isYesterdayKey && !isDate) {
               const d = new Date();
               d.setDate(d.getDate() - 1);
               const yyyy = d.getFullYear();
               const mm = (d.getMonth() + 1).toString().padStart(2, '0');
               const dd = d.getDate().toString().padStart(2, '0');
               label = `${yyyy}/${mm}/${dd}`;
          }

          return { index, text: label };
      }
      return null;
  }).filter((item): item is { index: number, text: string } => item !== null);

  let idxPriceCurrent = -1;
  let currentPriceDateLabel = '';

  // 排序日期欄位 (假設越後面的欄位日期越新)
  if (dateColIndices.length > 0) {
      const lastDateCol = dateColIndices[dateColIndices.length - 1];
      idxPriceCurrent = lastDateCol.index;
      currentPriceDateLabel = lastDateCol.text;
  } else {
      idxPriceCurrent = findCol(['收盤價', '收盤', '現價', '成交', 'price', 'current', '最近', 'close', 'last']);
      currentPriceDateLabel = '最新股價';
  }

  const idxPriceBase = findCol(['成本', '1/2', '01/02', '起始', 'base', 'open', 'start']); 
  const idxYield = findCol(['殖利率', 'yield', '配息率']);
  const idxReturn = findCol(['報酬', '損益', 'return']);

  // --- 3. Parse Data Rows ---
  for (let i = headerRowIndex + 1; i < lines.length; i++) {
    const row = parseCSVRow(lines[i]);

    if (idxCode !== -1 && row.length <= idxCode) continue;

    let code = '';
    let name = '';

    if (idxCode !== -1 && row[idxCode]) code = row[idxCode];
    if (idxName !== -1 && row[idxName]) name = row[idxName];

    if (!code) {
        if (row[0] && /^[0-9]{4,6}[A-Z]?$/.test(row[0])) code = row[0];
        else if (row[1] && /^[0-9]{4,6}[A-Z]?$/.test(row[1])) code = row[1];
    }

    code = code ? code.replace(/['"]/g, '').trim() : '';

    if (!code) continue;

    const category = CATEGORY_MAP[code];

    if (category) {
        if ((!name || name.includes('商品')) && idxCode !== -1 && row.length > idxCode + 1) {
            name = row[idxCode + 1];
        }

        let marketLabel = '上市';
        if (category === 'AE' || code.includes('B') || (name && name.includes('債'))) {
            marketLabel = '上櫃';
        }

        if (idxMarket !== -1 && row[idxMarket]) {
            const val = row[idxMarket].trim();
            if (val.includes('上櫃') || val.toLowerCase().includes('otc')) {
                marketLabel = '上櫃';
            } else if (val.includes('上市') || val.toLowerCase().includes('listed')) {
                marketLabel = '上市';
            }
        }

        const parseNum = (val: string) => {
            if (!val) return 0;
            const clean = val.replace(/[%$,]/g, '');
            const num = parseFloat(clean);
            return isNaN(num) ? 0 : num;
        };

        // 收集歷史股價
        const priceHistory: { date: string; price: number }[] = [];
        dateColIndices.forEach(col => {
            if (row[col.index]) {
                const p = parseNum(row[col.index]);
                if (p > 0) {
                    priceHistory.push({ date: col.text, price: p });
                }
            }
        });

        let priceCurrent = 0;
        let priceBase = 0;
        let dividendYield = 0;
        let returnRate = 0;

        if (idxPriceCurrent !== -1 && row[idxPriceCurrent]) {
            priceCurrent = parseNum(row[idxPriceCurrent]);
        }

        if (idxPriceBase !== -1 && row[idxPriceBase]) {
            priceBase = parseNum(row[idxPriceBase]);
        } else if (priceHistory.length > 0) {
            // 如果抓不到指定的 Base 欄位，嘗試用歷史數據的第一筆當 Base
            priceBase = priceHistory[0].price;
        }

        if (idxYield !== -1 && row[idxYield]) {
            dividendYield = parseNum(row[idxYield]);
        }

        if (idxReturn !== -1 && row[idxReturn]) {
            returnRate = parseNum(row[idxReturn]);
        } else if (priceBase > 0 && priceCurrent > 0) {
            returnRate = ((priceCurrent - priceBase) / priceBase) * 100;
        }

        if (priceCurrent === 0 && priceHistory.length > 0) {
             priceCurrent = priceHistory[priceHistory.length - 1].price;
        }

        etfs.push({
            code,
            name: name || code, 
            category,
            marketLabel, 
            priceBase: Number(priceBase.toFixed(2)),
            priceCurrent: Number(priceCurrent.toFixed(2)),
            dataDate: currentPriceDateLabel,
            dividendYield: Number(dividendYield.toFixed(2)),
            estYield: 0, 
            returnRate: Number(returnRate.toFixed(2)),
            totalReturn: Number(returnRate.toFixed(2)), 
            dividends: [],
            priceHistory // 寫入歷史資料
        });
    }
  }

  etfs.sort((a, b) => a.code.localeCompare(b.code));
  return etfs;
};

import React, { useState, useMemo } from 'react';
import { EtfData, CategoryKey, Dividend } from '../types';
import { ArrowUp, ArrowDown, Plus, TrendingUp, CircleAlert, ArrowLeft } from 'lucide-react';

interface Props {
  etfs: EtfData[];
  onAddToPortfolio: (etf: EtfData) => void;
  lastUpdated: Date | null;
}

// 擴展的 Tab 類型，包含原本的 CategoryKey 以及虛擬分類
type ExtendedCategoryKey = CategoryKey | 'International' | 'Active' | 'Semi';

// 定義分類配置
const CATEGORY_CONFIG: { key: ExtendedCategoryKey; label: string }[] = [
  { key: 'AA', label: '季一' },
  { key: 'AB', label: '季二' },
  { key: 'AC', label: '季三' },
  { key: 'AD', label: '月配' },
  { key: 'AE', label: '債券' },
  { key: 'International', label: '國際' }, // 原本的 AF 改為 國際
  { key: 'Active', label: '主動' },        // 新增
  { key: 'Semi', label: '半年' },          // 新增
];

// 使用者指定的債券排序列表
const BOND_SPECIFIC_ORDER = [
  '00937B', '00772B', '00933B', '00773B', // 月配
  '00720B', '00725B', '00724B',           // 季一
  '00679B', '00761B', '00795B',           // 季二
  '00687B', '00751B', '00792B'            // 季三
];

// 特殊分類代碼清單
const INTERNATIONAL_CODES = [
  '00645', '00646', '00662', '00757', '00762', '00830', '00885', '00893', '00895', '00909', '00910', '00911', '9910'
];

const ACTIVE_CODES = [
  '00980A', '00981A', '00982A', '00983A', '00984A', '00985A', '00986A', '00988A', '00989A'
];

const SEMI_CODES = [
  '0050', '006203', '00702', '00733', '00735', '00736', '00858', '00882', '00913', '00922', '00923', '00928', '00935'
];

// 輔助函式：判斷債券的配息週期類型 (用於顏色與詳細頁配息次數判斷)
const getBondType = (code: string): CategoryKey => {
    // 月配 (AD): 00937B, 00772B, 00933B, 00773B
    const monthlyBonds = ['00937B', '00772B', '00933B', '00773B'];
    if (monthlyBonds.some(b => code.includes(b))) return 'AD';

    // 季一 (AA): 00720B, 00725B, 00724B
    const groupQ1 = ['00720B', '00725B', '00724B'];
    if (groupQ1.some(b => code.includes(b))) return 'AA';

    // 季二 (AB): 00679B, 00761B, 00795B
    const groupQ2 = ['00679B', '00761B', '00795B'];
    if (groupQ2.some(b => code.includes(b))) return 'AB';

    // 季三 (AC): 00687B, 00751B, 00792B
    const groupQ3 = ['00687B', '00751B', '00792B'];
    if (groupQ3.some(b => code.includes(b))) return 'AC';

    // 其他未列出的債券預設歸類為季三
    return 'AC'; 
};

// Date Parsing Helper for Comparison
const getDateValue = (dateStr: string): number => {
    if (!dateStr) return 0;
    const cleanStr = dateStr.trim();

    // 處理 YYYYMM 格式 (例如 202412)
    if (/^\d{6}$/.test(cleanStr)) {
        const y = parseInt(cleanStr.substring(0, 4));
        const m = parseInt(cleanStr.substring(4, 6)) - 1;
        return new Date(y, m, 1).getTime();
    }

    // 處理一般日期格式 (2024/1/2, 2024-01-02, 2024.01.02)
    const standardDate = new Date(cleanStr.replace(/\./g, '/').replace(/-/g, '/'));
    if (!isNaN(standardDate.getTime())) {
        return standardDate.getTime();
    }
    return 0;
};

// Date helper for future check
const isFutureDate = (dateStr: string) => {
    const dateVal = getDateValue(dateStr);
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    return dateVal > today.getTime();
};

const PerformanceView: React.FC<Props> = ({ etfs, onAddToPortfolio, lastUpdated }) => {
  const [activeCat, setActiveCat] = useState<ExtendedCategoryKey>('AA');
  const [selectedEtf, setSelectedEtf] = useState<EtfData | null>(null);

  // 1. 篩選與排序資料
  const filteredEtfs = useMemo(() => {
    let result: EtfData[] = [];

    // 根據 activeCat 進行篩選
    if (['AA', 'AB', 'AC', 'AD', 'AE'].includes(activeCat)) {
        // 標準分類
        result = etfs.filter(e => e.category === activeCat);
    } else if (activeCat === 'International') {
        // 國際
        result = etfs.filter(e => INTERNATIONAL_CODES.includes(e.code));
    } else if (activeCat === 'Active') {
        // 主動 (注意：有些主動 ETF 可能已歸類在 AA/AB/AC，這裡使用代碼表重新撈取)
        result = etfs.filter(e => ACTIVE_CODES.includes(e.code));
    } else if (activeCat === 'Semi') {
        // 半年
        result = etfs.filter(e => SEMI_CODES.includes(e.code));
    } else {
        // Fallback (AF or unknown)
        result = etfs.filter(e => e.category === 'AF');
    }

    // 排序邏輯
    if (activeCat === 'AE') {
        // 債券特殊排序邏輯
        result.sort((a, b) => {
            const indexA = BOND_SPECIFIC_ORDER.indexOf(a.code);
            const indexB = BOND_SPECIFIC_ORDER.indexOf(b.code);

            if (indexA !== -1 && indexB !== -1) return indexA - indexB;
            if (indexA !== -1) return -1;
            if (indexB !== -1) return 1;
            return a.code.localeCompare(b.code);
        });
    } else {
        // 一般分類：依照股票代號排序
        result.sort((a, b) => a.code.localeCompare(b.code));
    }

    return result;
  }, [etfs, activeCat]);

  // 顯示用日期
  const displayDate = etfs.length > 0 && etfs[0].dataDate ? etfs[0].dataDate : '最新股價';

  // --- 顏色樣式邏輯 ---
  const getCardStyle = (etf: EtfData) => {
    let type: CategoryKey = 'AA';
    if (etf.category === 'AE') {
        type = getBondType(etf.code);
    } else {
        type = etf.category;
    }

    switch (type) {
        case 'AA': return 'bg-blue-50 border-blue-200';
        case 'AB': return 'bg-emerald-50 border-emerald-200';
        case 'AC': return 'bg-orange-50 border-orange-200';
        case 'AD': return 'bg-amber-50 border-amber-200';
        case 'AF': return 'bg-slate-100 border-slate-300'; // 其他分類: 淡灰色
        default: return 'bg-white border-slate-200';
    }
  };

  // --- 詳細資料頁面 (g. 詳細資料) ---
  if (selectedEtf) {
      // 設定顯示筆數邏輯
      let limit = 1;
      let labelText = '年配';

      // 1. 判斷月配 (AD 或 月配債)
      const monthlyBonds = ['00937B', '00772B', '00933B', '00773B'];
