          return etfs.filter(e => e.category === 'AD').sort((a,b) => a.code.localeCompare(b.code));
      }
      if (activeFilter === '債券') {
          return etfs.filter(e => e.category === 'AE').sort((a,b) => a.code.localeCompare(b.code));
      }

